  const skillDescriptions={commander:'軍団に編成すると攻撃力が4%上昇します。',cavalry:'総攻撃を選んだ合戦で、軍団の攻撃力が6%上昇します。',infantry:'正攻法を選んだ合戦で、軍団の攻撃力が5%上昇します。',ranged:'軍団に編成すると攻撃力が4%上昇します。',strategist:'伏兵を選んだ合戦で、軍団の攻撃力が8%上昇します。',administrator:'奉行に任命すると、政治力による施設補正に5%分を追加します。',farmer:'兵糧カテゴリの施設の奉行に任命すると、政治力による兵糧生産補正に10%分を追加します。',merchant:'商業カテゴリの施設の奉行に任命すると、政治力による金銭生産補正に10%分を追加します。',engineer:'木材・石材・防衛・研究カテゴリの施設の奉行に任命すると、政治力による施設補正に10%分を追加します。',medic:'軍団に編成すると、合戦で失う自軍の兵数を10%軽減します。'};
  const governorHelp={keep:'政治力に応じて武将の登用費用を軽減します。',farm:'政治力に応じて毎月の兵糧生産量を増やします。',market:'政治力に応じて毎月の金銭収入を増やします。',lumber:'政治力に応じて毎月の木材生産量を増やします。',quarry:'政治力に応じて毎月の石材生産量を増やします。',barracks:'政治力に応じて出陣兵の上限を増やし、募兵費用を軽減します。',wall:'政治力に応じて本拠の防衛力を高めます。',academy:'政治力に応じて研究に必要な金銭・木材・石材を軽減します。'};
  const skillIcons={commander:'flag',cavalry:'swords',infantry:'shield',ranged:'target',strategist:'book',administrator:'scroll',farmer:'wheat',merchant:'coins',engineer:'castle',medic:'plus'};
  const saveKey='sengoku-tento-save-v2', settingsKey='sengoku-tento-settings-v1', backupKey='sengoku-cloud-backups-v1';
  let linkedAtStart=false;try{linkedAtStart=!!JSON.parse(localStorage.getItem('sengoku-online-identity-v1')||'null')?.token;}catch(_){}
  let syncAccess={linked:linkedAtStart,ready:!linkedAtStart,writable:!linkedAtStart,reason:linkedAtStart?'pending':'local',message:linkedAtStart?'クラウドの最新データを確認しています。':'この端末に保存しています。'};
  const mutationActions=new Set(['toggle-time','upgrade','upgrade-castle','claim-quest','draw-officers','recruit-officer','scout','diplomacy','attack','assign-army','remove-army','assign-governor','remove-governor','recruit-troops','train','research','confirm-import','restore-admin-assets']);
  const roster=window.SENGOKU_OFFICERS||[], data=window.SENGOKU_DATA;
  let worldCatchingUp=false,worldCatchupTimer=null,worldClockStatusKey='',fieldActionPending=false,startPending=false,interactionEpoch=0,worldSettlementPending=false,worldSettlementRetryAt=0,renderedNavigation='',renderedSyncBanner='',staffBaseReady=false,roleEpoch=0;
  const interactionRestores=new WeakMap();
  for(const type of ['pointerdown','wheel','touchstart','touchmove','keydown'])document.addEventListener(type,()=>{interactionEpoch++;},{capture:true,passive:true});
  document.addEventListener('pointermove',event=>{if(event.buttons)interactionEpoch++;},{capture:true,passive:true});
  let newStartCastle='',game,saveEnabled=true,saveWarning='',currentView='town',filter={q:'',clan:'all',ownership:'all',sort:'lead',rank:'all',page:1},selectedCastle='',toastTimer,activeModal='',activeModalContext=null,battleTarget='',battleTactic='balanced',battleTroops=0,newClan='織田家',mapZoom=1,mapRegion='all',mapQuery='',facilityCategory='all',facilityQuery='',officerSection='archive',gachaOddsRank='D',gachaOddsPage=1,facilityPage=1,territoryPage=1,questPage=1,logPage=1,gachaHistoryPage=1,choicePage=1,choiceMode='army',choiceTarget='',musicPage=1,crestPage=1,crestQuery='';
  let settings={sound:false,volume:10,tips:true,musicMode:'auto',track:''};
  try{settings={...settings,...JSON.parse(localStorage.getItem(settingsKey)||'{}')};}catch(_){}
  settings.sound=false;
  try{const raw=localStorage.getItem(saveKey);startPending=raw===null;game=raw!==null?SengokuEngine.fromSave(raw,roster):new SengokuEngine({clan:'織田家',officers:roster});}catch(e){game=new SengokuEngine({clan:'織田家',officers:roster});saveWarning='保存を読み込めなかったため、自動保存を止めて仮プレイを開始しました。既存の保存データは上書きしていません。新しい物語やセーブ読込を確定すると置き換わります。';saveEnabled=false;}
  if(!game?.state){$('#main').innerHTML='<div class="loading-screen">ゲームの読み込みに失敗しました。再読み込みしてください。</div>';return;}
  const state=()=>game.state;
  function clanInfo(){return game.isAdmin?data.adminClan:game.isStaff?data.staffClan:data.clans.find(c=>c.name===state().clan)||data.clans[0];}
  function date(turn){if(turn===undefined)turn=window.SengokuWorldClock?.snapshot().clock?.calendar?.turn??state().turn;const calendar=game.calendar(turn);return {...calendar,season:['冬','春','春','春','夏','夏','夏','秋','秋','秋','冬','冬'][turn%12]};}
  function shortDate(turn=state().turn){const d=date(turn);return `${d.year}年${d.month}月`;}
  function constructionJobs(){return game.constructionJobs?.()||state().jobs;}
  function currentJob(kind,id,scope){const shared=scope?scope==='shared':game.isStaff&&(kind==='building'||kind==='castle'&&id==='sunpu');return constructionJobs().find(j=>j.kind===kind&&j.id===id&&Boolean(j.shared)===Boolean(shared));}
  function constructionCount(shared=false){return constructionJobs().filter(j=>j.kind!=='research'&&Boolean(j.shared)===shared).length;}
  function castleLevelLimit(id){return game.castleLevelLimit?.(id)||(data.castles.find(c=>c.id===id)?.majorCity?64:32);}
  function staffConstructionReady(){return game.isStaff&&staffBaseReady&&Boolean(game.getStaffBase?.());}
  function safeSettings(){try{localStorage.setItem(settingsKey,JSON.stringify(settings));}catch(_){}}
  function confirmedWorldClock(){const shared=window.SengokuWorldClock?.snapshot();return shared?.ready&&shared.clock?{...shared.clock,elapsedMs:shared.clock.confirmedElapsedMs??shared.clock.elapsedMs}:null;}
  function clockIsApplied(){if(!window.SengokuWorldClock)return true;const clock=confirmedWorldClock(),anchor=game?.state?.worldClock;return Boolean(clock&&anchor?.id===clock.id&&anchor.elapsedMs>=clock.elapsedMs&&anchor.elapsedMs<=clock.elapsedMs+5000);}
  function queueWorldProgress(){if(worldCatchupTimer===null)worldCatchupTimer=setTimeout(processWorldClock,0);}
  function canMutate(ignoreClock=false,allowSetup=false){const lease=!syncAccess.linked||(syncAccess.ready&&syncAccess.writable&&(!syncAccess.leaseExpiresAt||Date.parse(syncAccess.leaseExpiresAt)>Date.now()+1000));return lease&&!fieldActionPending&&!worldSettlementPending&&(allowSetup||!startPending)&&(ignoreClock||!worldCatchingUp&&clockIsApplied());}
  function canStartNew(){return canMutate(true,true)&&!worldCatchingUp&&(!game.isStaff||staffConstructionReady())&&(!window.SengokuWorldClock||Boolean(confirmedWorldClock()));}
  function syncMessage(){return worldSettlementPending?'占領した拠点の集計と報酬を同期しています。':syncAccess.message||(syncAccess.writable?'この端末で進行中 · 自動同期しています。':'他端末の進行を表示中です。「端末同期」から操作端末を切り替えられます。');}
  function requireWritable(){if(canMutate())return true;toast(worldSettlementPending?'占領した拠点の集計と報酬を同期しています。':startPending?'はじめに本拠の城を一つ選んでください。以前の進行がある場合は、引き継ぎ・復元から再接続できます。':fieldActionPending?'共通フィールド・資産・共同普請の結果を同期しています。':worldCatchingUp||window.SengokuWorldClock?.snapshot().ready&&!clockIsApplied()?'共通時刻までの進行を反映しています。':window.SengokuWorldClock&&!window.SengokuWorldClock.snapshot().ready?window.SengokuWorldClock.snapshot().message:syncMessage(),true);return false;}
  function save({allowClockCatchup=false}={}){const indicator=$('#save-indicator');if(startPending){if(indicator)indicator.textContent='開始する城を選択してください';return false;}if(!canMutate(allowClockCatchup)){if(indicator)indicator.textContent=syncAccess.ready?'クラウドの進行を表示中':'クラウドを確認中';return false;}if(!saveEnabled){if(indicator)indicator.textContent='自動保存できません';return false;}try{localStorage.setItem(saveKey,game.exportSave());if(indicator)indicator.textContent=syncAccess.linked?'端末に保存 · 同期中':'端末に自動保存済み';window.dispatchEvent(new CustomEvent('sengoku:game-saved'));return true;}catch(e){saveEnabled=false;saveWarning='このブラウザでは保存領域を利用できません。「保存・設定」でセーブを書き出してください。';if(indicator)indicator.textContent='セーブ書き出しを推奨';toast(saveWarning,true);return false;}}
  function syncBanner(){return syncAccess.linked?`<div id="sync-access-notice" class="sync-access-notice ${canMutate()?'sync-writable':'sync-readonly'}" role="status"><span>${icon(canMutate()?'check':'lock')}<span>${esc(syncMessage())}</span></span><button class="button small" data-action="open-sync">端末同期</button></div>`:'';}
  function backupCurrentSave(reason='cloud'){const raw=localStorage.getItem(saveKey)||(startPending?null:game.exportSave());if(!raw)return;const entries=JSON.parse(localStorage.getItem(backupKey)||'[]');const list=Array.isArray(entries)?entries:[];if(list[0]?.save===raw)return;list.unshift({savedAt:new Date().toISOString(),reason,save:raw});localStorage.setItem(backupKey,JSON.stringify(list.slice(0,5)));}
  function exportSyncBackup(){try{const list=JSON.parse(localStorage.getItem(backupKey)||'[]');if(!list.length){toast('同期前のバックアップはまだありません。');return;}downloadBlob(new Blob([list[0].save],{type:'application/json'}),'sengoku-taisen-before-sync.json');toast('直近の同期・読込前のセーブを書き出しました。「セーブデータを読み込む」から復元できます。');}catch(_){toast('バックアップを読み出せませんでした。',true);}}
  function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;toastTimer=setTimeout(()=>el.classList.remove('show'),5200);}
  function closeModal(){const m=$('#modal');if(m.open)m.close();activeModal='';activeModalContext=null;syncMusic();}
  function modal(title,subtitle,body,footer='',kind='',context=null){activeModal=kind;activeModalContext=context;$('#modal').classList.toggle('gacha-modal',kind==='gacha-result'||kind==='gacha-odds');$('#modal').classList.toggle('start-castle-modal',kind==='new');$('#modal-content').innerHTML=`<header class="modal-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close" aria-label="閉じる">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}`;if(!$('#modal').open)$('#modal').showModal();refreshLiveControls();refreshJobTimers();}
  function perform(result,{close=true,quiet=false}={}){if(!result?.ok){toast(result?.message||'実行できませんでした。',true);return false;}if(close)closeModal();save();render();playNote(659,.075);if(!quiet)toast(result.message);return true;}
  function hasResources(cost){return Object.keys(resNames).every(k=>state().resources[k]>=(cost?.[k]||0));}
  function costHtml(cost){return `<div class="cost">${Object.entries(resNames).filter(([k])=>cost?.[k]>0).map(([k,name])=>`<span data-cost-resource="${k}" data-cost-amount="${cost[k]}" class="${state().resources[k]<cost[k]?'insufficient':''}" title="${name}">${icon(resIcons[k])}${num(cost[k])}</span>`).join('')}${cost?.magatama?`<span class="magatama-cost">${icon('magatama')}${num(cost.magatama)}</span>`:''}${cost?.turns?`<span>${icon('calendar')}${cost.seconds||cost.turns*60}秒（1倍速）</span>`:''}</div>`;}
  function nav(){const items=[['town','castle','城下町'],['map','map','天下地図'],['field','flag','共通フィールド'],['officers','users','武将名鑑'],['crests','flag','家紋帳'],['army','swords','軍団編成'],['research','book','技術研究'],['council','scroll','軍議']];const markup=items.map(([id,ic,name])=>`<button class="nav-item ${currentView===id||(id==='town'&&currentView==='facilities')?'active':''}" data-view="${id}" ${currentView===id?'aria-current="page"':''}>${icon(ic)}<span>${name}</span>${id==='officers'?`<span class="nav-count">${state().officers.length}</span>`:''}</button>`).join('');if(markup!==renderedNavigation){$('#navigation').innerHTML=markup;renderedNavigation=markup;}}
  function clanCrest(name,size=36){return window.SengokuKamon?.render(name,{size,className:'clan-kamon'})||`<span class="mon" title="${esc(name)}">${esc(name.slice(0,1))}</span>`;}
  function officerCrest(o){if(!o)return `<span class="avatar officer-kamon is-empty" role="img" aria-label="武将未任命">${icon('plus')}</span>`;const crest=window.SengokuKamon?.render(o.clan,{size:48,className:'officer-house-kamon'})||'<img src="assets/kamon/unaffiliated.svg" alt="" width="48" height="48">';return `<span class="avatar officer-kamon" role="img" aria-label="${esc(o.name)}・${esc(o.clan)}の家紋" title="${esc(o.name)} · ${esc(o.clan)} · ${esc(o.rank)}"><span aria-hidden="true">${crest}</span></span>`;}
  function pageControls(action,page,pages,label=''){return `<div class="pagination"><button class="button small" data-action="${action}" data-delta="-1" ${page<=1?'disabled':''}>前の頁</button><span>${label?`${esc(label)} · `:''}${page} / ${pages}</span><button class="button small" data-action="${action}" data-delta="1" ${page>=pages?'disabled':''}>次の頁</button></div>`;}
  function crestResults(){const all=window.SengokuKamon?.entries()||[],list=all.filter(c=>!crestQuery||[c.clan,c.name,c.motif,c.crestName].filter(Boolean).join(' ').includes(crestQuery)),pages=Math.max(1,Math.ceil(list.length/20));crestPage=Math.max(1,Math.min(crestPage,pages));return `<div class="section-heading"><small>${list.length}勢力の家紋・群章</small><small>代表的な意匠を描き起こし</small></div><div class="kamon-catalog">${list.slice((crestPage-1)*20,crestPage*20).map(c=>`<button class="kamon-entry" data-action="crest-detail" data-id="${esc(c.clan)}">${clanCrest(c.clan,62)}<b>${esc(c.clan)}</b><small>${esc(c.name||c.crestName||c.motif||'勢力の紋')}</small></button>`).join('')||'<div class="empty">条件に合う家紋はありません。</div>'}</div>${pageControls('crest-page',crestPage,pages)}`;}
  function renderCrests(){return heading('諸家の家紋帳','FAMILY CRESTS · 旗に宿る系譜','城と武将、それぞれの家を表す紋をたどる。')+`<div class="toolbar"><div class="search-box">${icon('search')}<input class="input" id="crest-search" type="search" value="${esc(crestQuery)}" placeholder="家名・紋の名前を検索" aria-label="家紋を検索"></div><button class="button" data-view="officers">${icon('users')}武将名鑑へ</button></div><div id="crest-results">${crestResults()}</div><p class="notice">家紋には時代・分家による異形があります。ここでは各家の代表的な意匠をゲーム用に整理しています。「諸家」「在地衆」などは集合勢力の群章です。各紋を押すと採用理由・出典を確認できます。</p>`;}
  function crestModal(clan){const c=(window.SengokuKamon?.entries()||[]).find(x=>x.clan===clan);if(!c)return;modal(`${clan}の紋`,c.name||c.crestName||c.motif||'勢力の意匠',`<div class="crest-detail-art">${clanCrest(clan,176)}</div><p>${esc(c.note||c.description||'同家の代表的な意匠を、画面上で識別しやすい形に描き起こしています。')}</p>${c.status?`<div class="notice">${esc(c.kind==='group'?'複数家を表す創作群章':({documented:'資料に基づく代表家紋',traditional:'伝承意匠を基にしたゲーム用の図案',unverified:'系統の同定が難しいため識別章を採用'})[c.status]||c.status)}</div>`:''}<p class="subtitle">家紋は時代や分家により細部が異なります。ゲームにおける家名と人物の所属も、複数年代を合わせた設定です。</p><ul class="about-links">${(window.SengokuKamon?.getSources?.()||[]).filter(source=>(c.sourceIds||[]).includes(source.id)).map(source=>`<li><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.title)}</a></li>`).join('')}</ul><p class="subtitle">詳しい出典と図案の整理は <a href="SOURCES-KAMON.md" target="_blank" rel="noopener">家紋の出典資料</a> に記載しています。</p>`,`<button class="button primary" data-action="close">家紋帳へ戻る</button>`,'crest');}
  function renderHeader(){if(startPending){const d=date();$('#calendar').innerHTML=`<b>${d.year}年 ${d.month}月</b><span>全員共通の暦</span>`;$('#resources').innerHTML='<span class="start-campaign-status">本拠を選んで、新たな物語へ</span>';$('#clan-panel').innerHTML='<div class="clan-line">'+icon('flag')+'<div><b>出陣の準備</b><small>本拠はまだ確定していません</small></div></div>';$('#sound-button').innerHTML=icon(settings.sound?'sound':'mute');return;}const s=state(),d=date(),inc=game.income(),owned=game.ownedCastles().length,shared=window.SengokuWorldClock?.snapshot(),clock=shared?.clock;$('#calendar').innerHTML=`<b>${d.year}年 ${d.month}月<span class="season-symbol">${d.season}</span></b><span>${shared?.mode==='offline'?'オフライン版':shared?.ready?(clock?.running?'共通時間':'運営停止中'):'時刻を確認中'} · <i id="month-countdown" style="font-style:normal">${Math.ceil((60-(clock?.calendar?.elapsed??s.realtime?.elapsed??0))/(clock?.speed||1))}</i>秒</span>`;$('#resources').innerHTML=Object.keys(resNames).map(k=>`<div class="resource" title="${resNames[k]}：毎月 ${inc[k]>=0?'+':''}${num(inc[k])}"><span>${icon(resIcons[k],k)}</span><div><div class="resource-label">${resNames[k]}</div><div class="resource-amount">${num(s.resources[k])}<small class="resource-gain">${inc[k]>=0?'+':''}${num(inc[k])}</small></div></div></div>`).join('');$('#clan-panel').innerHTML=`<div class="clan-line">${clanCrest(s.clan,42)}<div><b>${esc(s.clan)}</b><small>${esc(clanInfo().leader)} の治世</small></div></div><div class="clan-progress"><i style="width:${owned/(game.unificationTarget?.()||data.castles.length)*100}%"></i></div><div class="clan-progress-label"><span>天下統一</span><span>${owned} / ${game.unificationTarget?.()||data.castles.length} 城</span></div>`;$('#sound-button').innerHTML=icon(settings.sound?'sound':'mute');$('#sound-button').setAttribute('aria-label',settings.sound?'BGMを停止':'BGMを再生');}
  function heading(title,en,subtitle){const s=state(),shared=window.SengokuWorldClock?.snapshot(),clock=shared?.clock,rt=clock?{running:clock.running,speed:clock.speed,elapsed:clock.calendar.elapsed}:s.realtime;return `<div class="page-heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="page-heading-actions"><div class="commands">指令 <span id="command-count">${s.command}</span><div class="command-pips" id="command-pips">${Array.from({length:game.commandMax()},(_,i)=>`<i class="${i<s.command?'filled':''}"></i>`).join('')}</div></div><button class="button gold" data-action="world-clock-info">${icon('calendar')}${shared?.mode==='offline'?'オフライン時間':'共通時間'}${game.isAdmin?'・管理':''}</button></div></div><div class="realtime-strip"><span id="shared-world-status" class="live-state ${shared?.ready&&rt.running?'running':''}">${esc(worldCatchingUp?'共通時刻までの進行を反映中':shared?.message||'共通時刻を確認しています。')}</span><button class="currency-chip" data-action="open-gacha" aria-label="勾玉を確認して武将招集へ">${icon('magatama')}<span>勾玉</span><b data-magatama-balance>${num(s.magatama)}</b></button><div class="time-track"><i id="month-progress" style="width:${(rt.elapsed||0)/60*100}%"></i></div><span class="shared-time-speed">${rt.speed||1}倍 · 1560〜1615年を周回</span></div>`;}
  function worldClockModal(){const shared=window.SengokuWorldClock?.snapshot(),clock=shared?.clock,d=date();modal('全プレイヤー共通の時間',`${d.year}年${d.month}月`, `<div class="world-clock-summary"><span>${icon('calendar')}</span><strong>1560年1月 → 1615年12月 → 1560年1月</strong><p>全プレイヤーが同じ年月を共有します。1倍速では実時間60秒がゲーム内の1か月。暦が一周すると占領した拠点を集計し、本拠以外の領地は初期配置に戻ります。最初に選んだ本拠へ戻り、運営は江戸城、スタッフは共同本拠の駿府城を維持します。武将・施設・資源、本拠の城郭レベルは引き継ぎます。</p><p>画面を閉じていても世界の時間は進み、再接続時に生産・普請・研究・月次処理が共通時刻へ追いつきます。区切りの時点で所有している本拠以外の城1つにつき、勾玉100・金銭1,000・兵糧1,000を一度だけ受け取れます。同盟・偵察と、本拠以外で進行中の城郭拡張はリセットされます。</p>${state().cycle?.latestReward?`<div class="notice cycle-reward-summary"><strong>前回の占領報酬</strong><p>対象 ${num(state().cycle.latestReward.captured)}城 · 勾玉 ${num(state().cycle.latestReward.magatama)} · 金銭 ${num(state().cycle.latestReward.gold)} · 兵糧 ${num(state().cycle.latestReward.rice)}</p></div>`:''}<div class="notice">${esc(shared?.message||'共通時刻を確認しています。')}${shared?.mode==='offline'?' このローカル環境では端末内の時間で進行します。':''}</div>${game.isAdmin&&shared?.mode!=='offline'?`<hr class="divider"><h3>運営の時間管理</h3><p>変更は全プレイヤーに反映されます。</p><div class="form-row"><label for="world-clock-speed">全体の速度</label><select id="world-clock-speed" class="select">${[1,2,4].map(speed=>`<option value="${speed}" ${clock?.speed===speed?'selected':''}>${speed}倍速</option>`).join('')}</select></div><div class="form-row"><label for="world-clock-running">全体の進行</label><select id="world-clock-running" class="select"><option value="true" ${clock?.running?'selected':''}>全員の時間を進める</option><option value="false" ${clock&&!clock.running?'selected':''}>全員の時間を停止する</option></select></div>`:''}</div>`,`<button class="button" data-action="close">戻る</button>${game.isAdmin&&shared?.mode!=='offline'?`<button class="button primary" data-action="world-clock-apply" ${!shared?.ready?'disabled':''}>全プレイヤーへ反映</button>`:''}`,'world-clock');}
  async function updateWorldClock(node){if(!game.isAdmin)return;const clock=window.SengokuWorldClock?.snapshot().clock;if(!clock)return;node.disabled=true;try{const result=await window.SengokuSocial?.setWorldClock?.({speed:Number($('#world-clock-speed').value),running:$('#world-clock-running').value==='true',revision:clock.revision});if(!result?.clock)throw Error('共通時刻を更新できませんでした。');window.SengokuWorldClock.accept(result.clock);closeModal();render();toast('全プレイヤー共通の時間設定を更新しました。');}catch(error){toast(error.message||'共通時刻の更新に失敗しました。',true);window.SengokuWorldClock?.refresh();node.disabled=false;}}


  function replaceMainContents(html){
    renderedSyncBanner=syncBanner();
    const main=$('#main'),map=currentView==='map'?main.querySelector('#world-map'):null,scene=currentView==='town'?main.querySelector('.town-scene'):null,board=scene?.querySelector('.town-scene-board');
    const geometry=scene?{scene:scene.getAttribute('style'),board:board?.getAttribute('style'),compact:scene.hasAttribute('data-town-compact'),tiny:scene.hasAttribute('data-town-art-small')}:null;
    const mapLayout=map?.closest('.world-layout-real');
    if(mapLayout?.parentElement===main){
      const template=document.createElement('template');template.innerHTML=html;
      const nextLayout=template.content.querySelector('.world-layout-real');
      if(nextLayout){
        const detail=mapLayout.querySelector('#castle-detail'),nextDetail=nextLayout.querySelector('#castle-detail');
        if(detail&&nextDetail)detail.innerHTML=nextDetail.innerHTML;
        // Never detach the live map: pointer capture and an in-progress pan
        // must survive a cloud save just like the camera and selected castle.
        for(const child of [...main.childNodes])if(child!==mapLayout)child.remove();
        let after=false;for(const child of [...template.content.childNodes]){if(child===nextLayout){after=true;continue;}if(after)main.appendChild(child);else main.insertBefore(child,mapLayout);}
        return;
      }
    }
    main.innerHTML=html;
    const nextScene=main.querySelector('.town-scene'),nextBoard=nextScene?.querySelector('.town-scene-board');
    if(geometry&&nextScene&&nextBoard){if(geometry.scene)nextScene.setAttribute('style',geometry.scene);if(geometry.board)nextBoard.setAttribute('style',geometry.board);nextScene.toggleAttribute('data-town-compact',geometry.compact);nextScene.toggleAttribute('data-town-art-small',geometry.tiny);nextScene.closest('.town-panel')?.toggleAttribute('data-town-compact',geometry.compact);}
  }
  function render(){renderHeader();nav();
    if(startPending){if(fieldController){fieldController.destroy();fieldController=null;}$('#main').dataset.view='start';$('#main').innerHTML=renderStartSelection();$('#resources').innerHTML='<span class="start-campaign-status">本拠を選んで、新たな物語へ</span>';$('#clan-panel').innerHTML='<div class="clan-line">'+icon('flag')+'<div><b>出陣の準備</b><small>本拠はまだ確定していません</small></div></div>';refreshLiveControls();window.SengokuDesktopFit?.refresh();return;}
    if(currentView==='field'&&fieldController&&$('#shared-field')){fieldController.update(fieldOptions());refreshLiveControls();refreshJobTimers();window.SengokuDesktopFit?.refresh();return;}
    if(fieldController){fieldController.destroy();fieldController=null;}
    const renderers={town:renderTown,facilities:renderFacilities,map:renderMap,field:renderField,officers:renderOfficers,army:renderArmy,research:renderResearch,council:renderCouncil,crests:renderCrests};$('#main').dataset.view=currentView;replaceMainContents((saveWarning?`<div class="notice">${esc(saveWarning)}</div>`:'')+(currentView==='town'?'':syncBanner())+(state().gameOver?`<div class="banner"><div><h2>落城 — 再起の時</h2><p>領国を失いました。新たな勢力と難易度で再び天下へ。</p></div><button class="button primary" data-action="new-game">新たに始める</button></div>`:state().won?`<div class="banner"><div><h2>天下統一</h2><p>統一対象の${game.unificationTarget?.()||data.castles.length}城が、あなたの旗の下に集いました。</p></div><button class="button gold" data-action="export-save">戦記を保存</button></div>`:'')+renderers[currentView]());document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));refreshLiveControls();refreshJobTimers();syncWorldMap();if(currentView==='field'&&window.SengokuField)fieldController=window.SengokuField.mount($('#shared-field'),fieldOptions());window.SengokuDesktopFit?.refresh();}
  function renderField(){return heading('共通フィールド','SHARED WORLD · 領主たちの天下','同じ世界に拠点を構え、攻撃と外交で関係を築く。')+'<div id="shared-field" class="shared-field"><div class="notice">領主たちの拠点を読み込んでいます。</div></div>';}
  function fieldOptions(){return{stateKey:'shared-field',identity:window.SengokuSocial?.getUser?.()||null,request:requestField,getState:()=>state(),getSyncStatus:()=>({...window.SengokuCloudSync?.getStatus?.(),writable:canMutate(),fieldPending:fieldActionPending,deviceId:window.SengokuCloudSync?.getDevice?.().id}),onRegister:()=>window.SengokuSocial?.open('profile'),onSync:()=>window.SengokuSocial?.open('sync'),onMutation:async()=>{},onMessage:toast};}
  async function requestField(route,{method='GET',data:payload}={}){
    const isGuild=route==='/guild/treasury/transfer'&&method==='POST',isStaff=route==='/staff/base/upgrade'&&method==='POST';
    if(!isGuild&&!isStaff&&(!/^\/field(?:\/me|\/attack|\/diplomacy)?(?:\?[^#]*)?$/.test(route)||!['GET','POST'].includes(method)))throw Error('共通フィールド・資産・共同普請の操作を確認してください。');
    const social=window.SengokuSocial,sync=window.SengokuCloudSync,send=isStaff?social?.staffRequest:isGuild?social?.guildRequest:social?.fieldRequest;if(!send)throw Error('共通フィールド・資産・共同普請に接続できません。');
    if(method==='GET'){if(route.split('?')[0]==='/field/me'){const [path,query='']=route.split('?'),params=new URLSearchParams(query);params.set('deviceId',sync?.getDevice?.().id||'');route=path+'?'+params;}return social.fieldRequest(route,{method});}
    const user=social.getUser?.();if(!user)throw Error('交流から領主を登録すると参加できます。');if(!sync?.getStatus?.().linked)throw Error('端末同期を確認してください。');if(fieldActionPending)throw Error('前の共通フィールド・資産・共同普請の操作を確認しています。');
    const staffEpoch=isStaff?roleEpoch:null;
    const verifyIdentity=()=>{if(String(social.getUser?.()?.id)!==String(user.id)){const error=Error('接続中の領主が変わったため、以前の結果の反映を取り消しました。');error.code='STALE_IDENTITY';throw error;}};
    const verifyGuild=()=>{if(isGuild&&(!payload?.guildId||String(social.getUser?.()?.guildId)!==String(payload.guildId))){const error=Error('所属するギルドが変わりました。ギルド画面を更新して確認してください。');error.code='STALE_GUILD';throw error;}};
    const verifyStaff=()=>{if(isStaff&&(staffEpoch!==roleEpoch||!game.isStaff||social.getUser?.()?.isStaff!==true||social.getUser?.()?.isAdmin===true||!staffConstructionReady())){const error=Error('スタッフ権限と共同拠点の接続を確認してください。');error.code='STALE_STAFF';throw error;}};
    verifyGuild();verifyStaff();await window.SengokuWorldClock?.refresh();verifyIdentity();verifyGuild();verifyStaff();processWorldClock();if(!requireWritable())throw Error('共通時刻と端末同期が整ってから操作してください。');if(!save())throw Error('セーブを保存できなかったため、操作を見送りました。');
    fieldActionPending=true;refreshLiveControls();let sent=false;
    const semantic={route,payload:isGuild?{guildId:payload.guildId,direction:payload.direction,resource:payload.resource,amount:payload.amount}:isStaff?{kind:payload.kind,id:payload.id}:payload},signature=JSON.stringify(semantic),pendingKey=isStaff?'sengoku-staff-upgrade-pending-v1:'+encodeURIComponent(String(user.id))+':'+encodeURIComponent(signature):isGuild?'sengoku-guild-transfer-pending-v1:'+encodeURIComponent(String(user.id))+':'+encodeURIComponent(signature):'sengoku-field-pending-v1';let pendingRecord;
    const clearPending=()=>{try{const stored=JSON.parse(localStorage.getItem(pendingKey)||'null');if(pendingRecord&&stored?.playerId===pendingRecord.playerId&&stored?.requestId===pendingRecord.requestId)localStorage.removeItem(pendingKey);}catch(_){}};
    try{
      const flushed=await sync.flush();if(!flushed?.ok||!sync.getStatus().writable)throw Error('最新の進行を同期できませんでした。もう一度お試しください。');
      verifyIdentity();verifyGuild();verifyStaff();
      try{const old=JSON.parse(localStorage.getItem(pendingKey)||'null');if(old&&old.playerId===String(user.id)&&old.signature===signature&&(isGuild||isStaff||Date.now()-old.createdAt<600000))pendingRecord=old;}catch(_){}
      if(!pendingRecord)pendingRecord={playerId:String(user.id),signature,requestId:payload?.requestId||crypto.randomUUID(),createdAt:Date.now(),...(isStaff?{baseRevision:game.getStaffBase().revision}:{})};
      localStorage.setItem(pendingKey,JSON.stringify(pendingRecord));
      const body={...payload,requestId:pendingRecord.requestId,deviceId:sync.getDevice().id,expectedRevision:sync.getStatus().revision,...(isStaff?{baseRevision:pendingRecord.baseRevision}:{})};sent=true;
      const result=await send(route,{method:'POST',data:body});
      verifyIdentity();verifyStaff();if(result.clock)window.SengokuWorldClock?.accept(result.clock);
      const needsReconcile=()=>Number.isSafeInteger(result.revision)&&sync.getStatus().revision<result.revision||isStaff&&(!Number.isSafeInteger(result.staffBase?.revision)||!staffConstructionReady()||game.getStaffBase().revision<result.staffBase.revision);
      let reconciled=await sync.refresh();verifyIdentity();verifyStaff();if((isGuild||isStaff)&&needsReconcile()){reconciled=await sync.refresh();verifyIdentity();verifyStaff();}
      if((isGuild||isStaff)&&(!reconciled?.ok||needsReconcile())){const error=Error(isStaff?'共同普請の結果を確認しています。通信回復後に同じ操作を再試行してください。二重には支払いません。':'資産の操作結果を保存先に確認しています。通信回復後に同じ操作を再試行してください。二重には移動しません。');error.code=isStaff?'STAFF_RECONCILE_PENDING':'GUILD_RECONCILE_PENDING';throw error;}
      clearPending();verifyGuild();verifyStaff();return result;
    }catch(error){if(error.status&&error.status<500)clearPending();if(sent&&String(social.getUser?.()?.id)===String(user.id))await sync.refresh();throw error;
    }finally{fieldActionPending=false;refreshLiveControls();queueWorldProgress();}
  }
