  function buildingCard(b){const lv=state().buildings[b.id]||0,job=currentJob('building',b.id),max=game.buildingMax(b.id),unlock=game.buildingUnlock?.(b.id)||{ok:true};return `<button class="building-card ${!unlock.ok?'locked-building':''}" data-category="${esc(b.category)}" data-action="building" data-id="${b.id}">${window.SengokuArt?.facility(b.id,'building-art',lv||1)||''}${job?`<span class="job-label">${job.shared?'共同普請':'普請中'}</span>`:''}<div class="building-top"><span class="building-symbol">${icon(b.icon)}</span><span class="building-level">${lv?`Lv.${lv}/${max}`:'未建設'}</span></div><h3>${esc(b.name)}</h3><p>${!unlock.ok?`天守 Lv.${unlock.requiredLevel}で解放`:esc(buildingOutput(b.id))}</p><div class="building-track">${Array.from({length:16},(_,i)=>`<i class="${i<Math.ceil(lv/2)?'on':''}"></i>`).join('')}</div>${job?`<small class="building-job-clock" data-job-clock="${job.kind}:${job.id}">${esc(jobClockText(job))}</small>`:''}</button>`;}
  const categoryNames={gold:'商業',rice:'農業・兵糧',wood:'林業・木材',stone:'鉱業・石材',military:'軍備',defense:'城郭・防衛',research:'学問・技術',diplomacy:'統治・外交'};
  function facilitiesResults(){const list=data.buildings.filter(b=>(facilityCategory==='all'||b.category===facilityCategory)&&(!facilityQuery||b.name.includes(facilityQuery)||b.description.includes(facilityQuery))),pages=Math.max(1,Math.ceil(list.length/6));facilityPage=Math.max(1,Math.min(facilityPage,pages));return `<div class="section-heading"><small>${list.length}施設 · 建設済み ${data.buildings.filter(b=>state().buildings[b.id]>0).length}/${data.buildings.length}</small><small>全施設 Lv.32まで強化</small></div><div class="facility-catalog">${list.slice((facilityPage-1)*6,facilityPage*6).map(b=>{const level=state().buildings[b.id]||0,j=currentJob('building',b.id),u=game.buildingUnlock(b.id),cost=game.costs(b.id);return `<section class="facility-entry" data-category="${esc(b.category)}">${window.SengokuArt?.facility(b.id,'facility-art',level||1)||''}<div class="facility-entry-heading"><span class="building-symbol">${icon(b.icon)}</span><div><small>${categoryNames[b.category]||'城下町'}</small><h3>${esc(b.name)}</h3></div><span class="facility-seal">${level?`<b>${level}</b><small>/ 32</small>`:'<small>未建設</small>'}</span></div><p>${esc(b.description)}</p><div class="facility-effect">${esc(b.effectText||b.output)}</div>${j?`<div class="notice">Lv.${j.targetLevel}へ${j.shared?'共同普請':'普請'}中 · <span data-job-clock="${j.kind}:${j.id}">${esc(jobClockText(j))}</span>${sharedJobAttribution(j)}</div><div class="progress"><i data-job-progress="${j.kind}:${j.id}" style="width:${game.constructionProgress(j)}%"></i></div>`:level>=32?'<div class="notice">最高段階に到達</div>':`${costHtml(cost)}<button class="button ${u.ok?'gold':''} full" data-action="building" data-id="${b.id}">${u.ok?(level?'増築・奉行を管理':'建設する'):esc(u.reason||`天守Lv.${u.requiredLevel}で解放`)}</button>`}</section>`;}).join('')||'<div class="empty"><p>条件に合う施設はありません。</p></div>'}</div>${pageControls('facility-page',facilityPage,pages)}`;}
  function renderFacilities(){return heading('城下普請帳','CONSTRUCTION LEDGER · 六十四の礎',`${data.buildings.length}種類の施設を、各32段階まで育てる。`)+`${staffBaseNotice()}<div class="facility-banner"><div><span class="eyebrow">YOUR GROWING DOMAIN</span><h2>一つの普請が、国の力になる。</h2><p>生産、軍備、外交。領国の個性を、あなたの采配で。</p></div><div class="facility-banner-count"><b>${data.buildings.filter(b=>state().buildings[b.id]>0).length}</b><span> / 64 施設</span></div></div><div class="toolbar"><div class="search-box">${icon('search')}<input class="input" id="facility-search" type="search" placeholder="施設名・効果を検索" value="${esc(facilityQuery)}" aria-label="施設を検索"></div><select id="facility-category" class="select" aria-label="施設の分類"><option value="all">すべての施設</option>${Object.entries(categoryNames).map(([k,n])=>`<option value="${k}" ${facilityCategory===k?'selected':''}>${n}</option>`).join('')}</select><button class="button" data-view="town">${icon('castle')}城下町に戻る</button></div><div class="notice">施設と城郭を合わせて同時に${game.constructionSlots()}件まで普請できます。未建設の施設はLv.1から育成し、全施設の上限はLv.32です。奉行に任命した家臣の能力・特技も効果に影響します。</div><div id="facility-results">${facilitiesResults()}</div>`;}

