  function buildingModal(id){const b=data.buildings.find(b=>b.id===id);if(!b)return;const s=state(),lv=s.buildings[id]||0,cost=game.costs(id),unlock=game.buildingUnlock(id),job=currentJob('building',id),governor=game.officer(s.governors[id]),canGov=lv>0;modal(`${b.name}　${lv?`Lv.${lv} / 32`:'未建設'}`,game.isStaff?'スタッフ共同普請 · 駿府城':'城下町の発展',`${window.SengokuArt?.facility(id,'facility-modal-art',lv||1)||''}${game.isStaff?'<p class="notice staff-base-note">全スタッフの城下町で成長を共有します。あなたの資源と指令1回で共同普請を始めます。奉行はあなた個人の任命です。</p>':''}<p>${esc(b.description)}</p><div class="stat-row"><span>現在の効果</span><b>${buildingOutput(id)}</b></div><button class="button small full" style="margin:13px 0" data-action="preview-art" data-kind="facility" data-id="${id}">${icon('eye')}32段階の姿を見る</button>${job?`<div class="notice">Lv.${job.targetLevel}へ普請中 · <span data-job-clock="${job.kind}:${job.id}">${esc(jobClockText(job))}</span>${sharedJobAttribution(job)}</div><div class="progress"><i data-job-progress="${job.kind}:${job.id}" style="width:${game.constructionProgress(job)}%"></i></div>`:lv<game.buildingMax(id)?`<h3>${lv?`Lv.${lv+1}へ増築`:'Lv.1を建設'}</h3>${!unlock.ok?`<div class="notice">${esc(unlock.reason)}</div>`:''}<p>指示を1回使います。施設と城郭を合わせて同時に${game.constructionSlots()}件まで普請できます。</p>${costHtml(cost)}`:'<div class="notice">最高レベルに達しています。</div>'}${canGov?`<hr class="divider"><div class="stat-row"><span>奉行</span><b>${governor?esc(governor.name):'未任命'}</b></div><p>${esc(game.governorDescription?.(id)||governorHelp[id]||b.description)}軍団との兼任はできません。任命には指示を使いません。</p><button class="button small gold" style="margin-top:14px" data-action="pick-governor" data-id="${id}">${icon('users')}奉行を選ぶ</button>`:''}`,`<button class="button" data-action="close">閉じる</button>${!job&&lv<game.buildingMax(id)?`<button class="button primary" data-action="upgrade" data-id="${id}" ${!hasResources(cost)||!unlock.ok||s.command<1||s.gameOver?'disabled':''}>${icon('castle')}${game.isStaff?'共同普請する':lv?'増築する':'建設する'}</button>`:''}`,'building',{id});}
  let worldMapController=null,worldMapElement=null,fieldController=null;
  function syncWorldMap(){const container=$('#world-map');if(currentView!=='map'||!container){worldMapController?.destroy();worldMapController=null;worldMapElement=null;return;}if(!window.SengokuWorldMap){container.innerHTML='<p class="notice">地図を読み込めませんでした。再読み込みしてください。</p>';return;}const s=state(),reachable=new Set(game.adjacentTargets().map(c=>c.id)),options={stateKey:'campaign-map',castles:data.castles.map(c=>({...c,...s.castles[c.id],reachable:reachable.has(c.id)})),selectedId:selectedCastle,region:mapRegion,clan:s.clan,isAdmin:game.isAdmin,isStaff:game.isStaff,homeId:s.home,treaties:s.treaties,turn:s.turn,crestFor:name=>window.SengokuKamon?.url(name),onSelect:id=>{if(id==='edo'&&!game.isAdmin||id==='sunpu'&&!game.isStaff)return;selectedCastle=id;preserveInteraction($('#main'),render);}};if(worldMapController&&worldMapElement===container)worldMapController.update(options);else{worldMapController?.destroy();worldMapElement=container;worldMapController=window.SengokuWorldMap.mount(container,options);}}
  function renderMap(){if(!selectedCastle||selectedCastle==='edo'&&!game.isAdmin)selectedCastle=game.adjacentTargets().sort((a,b)=>a.troops-b.troops)[0]?.id||state().home;const owned=game.ownedCastles(),reachable=new Set(game.adjacentTargets().map(c=>c.id));return heading('天下地図','JAPAN · 山河を越えて、天下へ','日本列島の地形と城跡の位置をたどり、領国を広げる。')+`<div class="toolbar map-toolbar"><div class="search-box">${icon('search')}<input id="castle-search" class="input" type="search" value="${esc(mapQuery)}" placeholder="城名・勢力・国名で探す" aria-label="城を検索"></div><select id="map-region" class="select" aria-label="地図の地方"><option value="all">全国128城</option>${[...new Set(data.castles.map(c=>c.region))].map(r=>`<option ${mapRegion===r?'selected':''}>${r}</option>`).join('')}</select><button class="button small" data-action="map-home">${icon('castle')}本拠へ</button><button class="button small" data-action="map-fit">${icon('expand')}列島全景</button></div><div class="world-layout world-layout-real"><section class="geographic-map-panel" aria-label="日本列島の地理に基づく天下地図"><div id="world-map" class="geographic-map-host"></div></section><aside id="castle-detail" class="panel castle-detail">${castleDetail(selectedCastle)}</aside></div><div class="section-heading"><h2>${icon('flag')}拠点一覧</h2><small>自領 ${owned.length}城 · 進軍できる隣接拠点 ${reachable.size}城</small></div><div id="territory-results">${territoryResults()}</div><p class="notice map-data-note">海岸線は現代の地理データ、城は城跡・施設の代表地点に基づきます。戦国期の海岸線や国境を測量復元したものではありません。勢力配置・進軍経路はゲーム設定です。江戸城は運営専用です。</p>`;}
  function territoryResults(){const reachable=new Set(game.adjacentTargets().map(c=>c.id)),s=state();const list=data.castles.map(c=>game.castle(c.id)).filter(c=>(mapRegion==='all'||c.region===mapRegion)&&(!mapQuery||c.name.includes(mapQuery)||c.owner.includes(mapQuery)||c.province.includes(mapQuery))).sort((a,b)=>Number(reachable.has(b.id))-Number(reachable.has(a.id))||Number(b.owner===s.clan)-Number(a.owner===s.clan)),pages=Math.max(1,Math.ceil(list.length/4));territoryPage=Math.max(1,Math.min(territoryPage,pages));return `<div class="territory-list all-territories">${list.slice((territoryPage-1)*4,territoryPage*4).map(c=>`<button class="territory-row ${selectedCastle===c.id?'active':''}" data-action="select-castle" data-id="${c.id}" ${c.id==='edo'&&!game.isAdmin?'disabled title="運営専用"':c.id==='sunpu'&&!game.isStaff?'disabled title="スタッフ専用"':''}>${window.SengokuArt?.castle(c.id,'territory-art',c.level)||''}<div class="territory-name">${clanCrest(c.owner,23)}${esc(c.name)}<br><small>${esc(c.owner)} · ${esc(c.province)}</small></div><div class="territory-numbers"><small>${num(c.troops)}兵</small><br><span class="territory-label ${c.owner===s.clan?'own':reachable.has(c.id)?'reachable':''}">${c.id==='edo'&&!game.isAdmin?'運営専用':c.id==='sunpu'&&!game.isStaff?'スタッフ専用':c.owner===s.clan?'自領':reachable.has(c.id)?'隣接':'遠方'}</span></div></button>`).join('')||'<div class="empty"><p>条件に合う拠点はありません。</p></div>'}</div>${pageControls('territory-page',territoryPage,pages,`${list.length}城`)}`;}

  function castleDetail(id){
    const c=game.castle(id);if(!c)return '';
    const s=state(),allowed=game.canOwnCastle?.(id)!==false,own=c.owner===s.clan&&allowed,shared=game.isStaff&&id==='sunpu',adj=game.adjacentTargets().some(t=>t.id===id),ally=(s.treaties[c.owner]||0)>s.turn,scouted=(s.scouted[id]||0)>s.turn,job=currentJob('castle',id),benefit=game.castleBenefits(id),cost=game.castleUpgradeCost(id),limit=castleLevelLimit(id);
    return `<div class="castle-banner">${window.SengokuArt?.castle(id,'castle-detail-art',c.level)||''}${icon('castle')}</div><div class="castle-info"><div class="eyebrow">${esc(c.region)} · ${esc(c.province)}国</div><h2>${esc(c.name)}</h2>${c.majorCity?`<span class="major-city-badge">${icon('castle')}大都市拠点${id==='edo'?' · 運営専用・占領不可':id==='sunpu'?' · スタッフ共同拠点・占領不可':''}</span>`:''}<span class="castle-status ${own?'':'enemy'}">${clanCrest(c.owner,25)}${own?'自領':ally?'同盟勢力':'他勢力'} · ${esc(c.owner)}</span><div class="stat-row"><span>城郭レベル</span><b>Lv.${c.level} / ${limit}</b></div><div class="stat-row"><span>守備兵</span><b>${num(c.troops)} 人</b></div><div class="stat-row"><span>城壁</span><b>Lv.${c.wall}</b></div><div class="stat-row"><span>街道</span><b>${c.neighbors.length} 城に接続</b></div>${scouted?'<div class="stat-row"><span>偵察効果</span><b>攻撃力 +10%</b></div>':''}</div><button class="button small full" data-action="preview-art" data-kind="castle" data-id="${id}">${icon('eye')}32段階の城郭を見る</button>${c.level>32?'<p class="subtitle">城郭は最終形態の姿で、さらに強化されています。</p>':''}${own?`<div class="castle-expansion"><h3>${icon('castle')}${shared?'駿府城の共同普請':'城郭の拡張'}</h3>${shared?'<p class="notice staff-base-note">城郭の成長は全スタッフ共通です。普請を指示するあなたが資源と指令1回を支払います。</p>':''}<p>城郭による防衛補正 +${benefit.defensePercent}%<br>領地の基礎収入：金銭${num(benefit.gold)}・兵糧${num(benefit.rice)} /月</p>${job?`<div class="notice">Lv.${job.targetLevel}へ${shared?'共同普請':'拡張'}中 · <span data-job-clock="castle:${id}">${esc(jobClockText(job))}</span>${sharedJobAttribution(job)}</div><div class="progress"><i data-job-progress="castle:${id}" style="width:${game.constructionProgress(job)}%"></i></div>`:c.level>=limit?`<div class="notice">城郭は最高のLv.${limit}です。</div>`:`${costHtml(cost)}<button class="button gold full${shared?' staff-base-upgrade':''}" data-action="upgrade-castle" data-id="${id}" ${shared&&!staffConstructionReady()?'disabled':''}>Lv.${c.level+1}へ${shared?'共同普請する':'拡張する'}</button>`}<small>${shared?'全スタッフ共通の':'個人の'}施設・城郭の普請枠を使用します。城郭レベルは天守などの施設レベルとは別に育ちます。</small></div><div class="notice">${id===s.home?'あなたの本拠です。城下町から施設も増築できます。':'この城を拠点として、さらに隣接する城へ進軍できます。領地収入は時間経過に応じて自動で加算されます。'}</div><button class="button gold full" data-view="town">${icon('castle')}城下町へ</button>`:!allowed?`<div class="notice">${id==='sunpu'?'駿府城はスタッフ共同の保護された本拠です。':'江戸城は運営専用の保護された本拠です。'}占領・襲撃はできません。</div>`:`<div><button class="button primary full" data-action="prepare-battle" data-id="${id}" ${!adj||ally||s.gameOver?'disabled':''}>${icon('swords')}${ally?'同盟期間中':adj?'この城へ出陣':'自領から遠い拠点'}</button><button class="button full" data-action="scout" data-id="${id}" ${!adj||s.command<1||scouted||s.gameOver?'disabled':''}>${icon('eye')}${scouted?'偵察済み':`偵察　金銭${game.scoutCost().gold}`}</button><button class="button ghost full" data-action="diplomacy-info" data-id="${id}" ${ally||s.gameOver?'disabled':''}>${icon('handshake')}${ally?`同盟あと${s.treaties[c.owner]-s.turn}か月`:'この勢力と同盟'}</button></div>`}`;
  }

  function artPreviewModal(kind,id,level){const isCastle=kind==='castle',info=isCastle?game.castle(id):data.buildings.find(b=>b.id===id);if(!info)return;const actual=isCastle?info.level:state().buildings[id],chosen=Math.max(1,Math.min(32,Number.isInteger(level)?level:actual||1));modal(`${info.name} · 32段階の絵巻`,`${isCastle?'城郭':'施設'}の現在レベル：${actual?`Lv.${actual}`:'未建設'}`,`<div class="art-preview-stage" id="level-art-preview">${(isCastle?window.SengokuArt?.castle(id,'level-preview-art',chosen):window.SengokuArt?.facility(id,'level-preview-art',chosen))||icon('castle')}</div><div class="art-level-controls"><button class="button small" data-action="art-level-step" data-delta="-1" ${chosen===1?'disabled':''}>前の姿</button><strong id="art-preview-caption">Lv.${chosen} / 32</strong><button class="button small" data-action="art-level-step" data-delta="1" ${chosen===32?'disabled':''}>次の姿</button></div><label for="art-preview-level">見たいレベルを選ぶ</label><input class="range" id="art-preview-level" type="range" min="1" max="32" step="1" value="${chosen}"><p class="subtitle">32段階の完成イラストを閲覧できます。表示する姿を変えても、実際のレベル・資源・進行状態は変わりません。</p>`,`<button class="button primary" data-action="close">閉じる</button>`,'art-preview',{kind,id,level:chosen});}
  function updateArtPreview(level){if(activeModal!=='art-preview'||!activeModalContext)return;const c=activeModalContext,chosen=Math.max(1,Math.min(32,Math.floor(Number(level)||1)));c.level=chosen;const art=c.kind==='castle'?window.SengokuArt?.castle(c.id,'level-preview-art',chosen):window.SengokuArt?.facility(c.id,'level-preview-art',chosen);$('#level-art-preview').innerHTML=art||icon('castle');$('#art-preview-caption').textContent=`Lv.${chosen} / 32`;$('#art-preview-level').value=chosen;document.querySelectorAll('[data-action="art-level-step"]').forEach(el=>el.disabled=Number(el.dataset.delta)<0?chosen===1:chosen===32);}
  function portrait(o){if(window.SengokuArt?.portrait)return window.SengokuArt.portrait(o);const n=o.name.split('').reduce((a,c)=>a+c.charCodeAt(0),0),horn=n%3;return `<svg class="portrait" viewBox="0 0 120 130" aria-hidden="true"><defs><linearGradient id="armor-${o.id}" x2="1" y2="1"><stop stop-color="#b59b6d" stop-opacity=".6"/><stop offset="1" stop-color="#242c2c"/></linearGradient></defs><path d="M6 130q3-36 30-40l24-5 24 5q27 4 30 40" fill="url(#armor-${o.id})" stroke="currentColor" stroke-width="1"/><path d="m29 97-7 27m69-27 7 27M33 106h54M29 115h62M38 94l22 19 22-19M60 113v17" fill="none" stroke="currentColor" opacity=".7"/><path d="M40 55v22q3 17 20 18 17-1 20-18V55Z" fill="#b4a58b"/><path d="M32 60q0-35 28-35t28 35l-9 9-3-17H44l-4 17Z" fill="#2c3434" stroke="currentColor"/><path d="m27 58 13-6h40l13 6-5 8H32Z" fill="#3a3b30" stroke="currentColor"/><path d="m40 27-13-17 7 28m46-11 13-17-7 28" fill="none" stroke="currentColor" stroke-width="3"/>${horn===0?'<path d="m60 8-6 15 6 7 6-7Z" fill="currentColor"/>':horn===1?'<circle cx="60" cy="22" r="8" fill="none" stroke="currentColor" stroke-width="2"/>':'<path d="M45 16q15 18 30 0" fill="none" stroke="currentColor" stroke-width="3"/>'}<path d="m47 65 7 1m12 0 7-1m-13 4-2 9h5m-11 6q8 4 16 0" fill="none" stroke="#3d3932" stroke-width="1.5"/><path d="m40 72-8 10v11l12-4M80 72l8 10v11l-12-4" fill="#303833" stroke="currentColor" opacity=".7"/></svg>`;}
  function filteredOfficers(){const selectedRank=filter.rank==='all'?undefined:filter.rank,normalize=value=>String(value??'').replace(/德/g,'徳'),query=normalize(filter.q);let list=roster.map(o=>game.officer(o.id,selectedRank)).filter(o=>(!query||[o.name,o.clan,o.region].some(value=>normalize(value).includes(query)))&&(filter.clan==='all'||o.clan===filter.clan)&&(filter.ownership==='all'||(filter.ownership==='owned'?game.ownsVariant(o.id,o.rank):!game.ownsVariant(o.id,o.rank))));const rarity={D:0,C:1,B:2,A:3,S:4,SS:5,SSS:6,U:7};list.sort((a,b)=>filter.sort==='name'?a.name.localeCompare(b.name,'ja'):filter.sort==='rarity'?(rarity[b.rank]||0)-(rarity[a.rank]||0)||b.lead-a.lead:b[filter.sort]-a[filter.sort]);return list;}
  function officerCard(o){return `<button class="officer-card" data-rank="${o.rank}" data-action="officer" data-id="${o.id}"><div class="officer-art"><span class="clan-script clan-script-kamon">${clanCrest(o.clan,30)}</span>${portrait(o)}<span class="rarity rank-${o.rank}">${o.rank}</span>${game.ownsVariant(o.id,o.rank)?'<span class="owned-tag">絵巻所持</span>':'<span class="owned-tag unowned-variant">未所持</span>'}</div><div class="officer-content"><small>${esc(o.clan)} · ${esc(o.region)}</small><h3>${esc(o.name)}</h3><div class="mini-stats">${[['lead','統率'],['valor','武勇'],['intellect','知略'],['politics','政治']].map(([k,n])=>`<span>${n}<b>${o[k]}</b></span>`).join('')}</div><div class="skill-tag">${icon(skillIcons[o.skill]||'flag')}${esc(skillNames[o.skill]||o.skill)}</div></div></button>`;}
  function officersResults(){const list=filteredOfficers(),pages=Math.max(1,Math.ceil(list.length/8));filter.page=Math.min(filter.page,pages);return `<div class="section-heading" style="margin-top:0"><small>${num(list.length)}名 · ${filter.rank==='all'?'最高所持・基本ランク':`${filter.rank}ランクの絵巻`} · ${filter.page} / ${pages}頁</small><small>本作用に描き起こした創作肖像</small></div><div class="officers-grid">${list.slice((filter.page-1)*8,filter.page*8).map(officerCard).join('')||`<div class="empty">${icon('search')}<p>条件に合う絵巻が見つかりません。</p></div>`}</div><div class="pagination"><button class="button small" data-action="officer-page" data-delta="-1" ${filter.page<=1?'disabled':''}>前の頁</button><span>${filter.page} / ${pages}</span><button class="button small" data-action="officer-page" data-delta="1" ${filter.page>=pages?'disabled':''}>次の頁</button></div>`;}
  function renderOfficers(){if(officerSection==='gacha')return heading('武将招集','WARLORD SUMMON · 群雄招来','勾玉を捧げ、まだ見ぬ英傑との縁を結ぶ。')+officerTabs()+renderGacha();const clans=[...new Set(roster.map(o=>o.clan))].sort((a,b)=>a.localeCompare(b,'ja'));return heading('武将名鑑','OFFICER ARCHIVE · 人こそ城',`${num(roster.length)}名 × 8ランク · 所持対象 ${num(game.collection().totalVariants)}種の絵巻。`)+officerTabs()+`<div class="toolbar"><div class="search-box">${icon('search')}<input class="input" id="officer-search" type="search" value="${esc(filter.q)}" placeholder="武将名・勢力・地方で検索" aria-label="武将を検索"></div><select class="select" id="officer-clan" aria-label="勢力で絞り込む"><option value="all">すべての勢力</option>${clans.map(c=>`<option ${filter.clan===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="select" id="officer-rank" aria-label="武将ランク"><option value="all">最高所持・基本ランク</option>${window.SENGOKU_RANKS.map(r=>`<option value="${r}" ${filter.rank===r?'selected':''}>${r}ランク</option>`).join('')}</select><select class="select" id="officer-sort" aria-label="武将の並び順">${[['lead','統率の高い順'],['valor','武勇の高い順'],['intellect','知略の高い順'],['politics','政治の高い順'],['rarity','ランクの高い順'],['name','名前順']].map(([v,n])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${n}</option>`).join('')}</select><div class="tabs" role="group" aria-label="登用状況">${[['all','すべて'],['owned','絵巻所持'],['free','未所持']].map(([v,n])=>`<button class="${filter.ownership===v?'active':''}" data-action="officer-filter" data-id="${v}">${n}</button>`).join('')}</div></div><div id="officer-results">${officersResults()}</div><div class="notice">登場年代を越えた「群雄集結」シナリオです。能力・特技・格付けはゲーム用の創作で、歴史上の評価ではありません。全256名それぞれに D・C・B・A・S・SS・SSS・U の8種類、計2,048種の絵巻があります。ランクを選ぶと、そのランクの全武将を閲覧できます。軍団・奉行には所持する最高ランクの能力が反映されます。</div>`;}
  function officerTabs(){const collection=game.collection();return `<div class="officer-subnav"><div class="tabs" role="group" aria-label="武将の画面"><button class="${officerSection==='archive'?'active':''}" data-action="officer-section" data-id="archive" aria-pressed="${officerSection==='archive'}">${icon('users')}武将名鑑</button><button class="${officerSection==='gacha'?'active':''}" data-action="officer-section" data-id="gacha" aria-pressed="${officerSection==='gacha'}">${icon('magatama')}武将招集</button></div><span class="collection-count">家臣 ${collection.officers} / ${roster.length}名<br>絵巻 ${num(collection.variants)} / ${num(collection.totalVariants)}種</span></div>`;}
  function renderGacha(){const s=state(),g=data.gacha,odds=game.gachaOdds(),history=s.gachaHistory.slice(0,48),pages=Math.max(1,Math.ceil(history.length/4));gachaHistoryPage=Math.max(1,Math.min(gachaHistoryPage,pages));const recent=history.slice((gachaHistoryPage-1)*4,gachaHistoryPage*4);return `<section class="gacha-sanctuary"><div class="gacha-sanctuary-art" aria-hidden="true">${icon('magatama')}<span>縁</span></div><div class="gacha-hero-copy"><div class="eyebrow">A FATE WORTH FOLLOWING</div><h2>次なる英傑と、天下へ。</h2><p>全${roster.length}名・8ランク、${num(game.collection().totalVariants)}種の絵巻が招集対象。<br>同じ武将でも、ランクごとに姿と能力が異なります。</p><div class="gacha-balance"><span>${icon('magatama')}所持勾玉</span><b data-magatama-balance>${num(s.magatama)}</b></div><div class="gacha-actions"><button class="button gold" data-action="draw-officers" data-count="1">1回招集 <span>${icon('magatama')}${num(g.singleCost)}</span></button><button class="button primary" data-action="draw-officers" data-count="10">10回招集 <span>${icon('magatama')}${num(g.tenCost)}</span></button></div><p class="gacha-smallprint">指令の消費なし · 10回招集は勾玉${num(g.singleCost*10-g.tenCost)}お得</p></div></section><div class="gacha-details-grid"><section class="panel"><div class="panel-heading"><h2>${icon('crown')}招集の提供割合</h2><button class="text-link" data-action="gacha-odds">全武将の割合を見る</button></div><div class="gacha-rates">${odds.map(r=>`<div><span class="gacha-rank rank-${r.rank}">${r.rank}</span><b>${r.rate}<small>%</small></b><small>${r.count}名</small></div>`).join('')}</div><p class="subtitle">ランク内の対象武将から等確率で抽選。德川家康Uは運営専用です。1回・10回とも同じ割合で1枠ずつ抽選します。確定枠や天井はありません。</p><div class="notice">同じ武将でも別ランクなら新規絵巻です。同じ武将・同じランクの重複だけが勾玉${g.duplicateRefund}に変換されます。戦力には最高所持ランクを反映します。</div></section><section class="panel"><div class="panel-heading"><h2>${icon('magatama')}勾玉を集める</h2><small>プレイで獲得</small></div><div class="gacha-source"><span>${icon('calendar')}月次褒賞</span><b>+${g.monthlyReward}<small> / ゲーム内1か月</small></b></div><div class="gacha-source"><span>${icon('castle')}城の初攻略</span><b>+${g.firstCaptureReward}<small> / 1城につき1度</small></b></div><div class="gacha-source"><span>${icon('scroll')}領主の任務</span><b>+100〜1,000<small> / 任務</small></b></div><p class="subtitle">新しい物語は勾玉${num(g.initial)}で開始します。勾玉の購入や現金の支払いはありません。</p><button class="button full" data-view="council" style="margin-top:17px">${icon('target')}任務と報酬を確認する</button></section></div><div class="section-heading"><h2>${icon('scroll')}最近の招集</h2><small>累計 ${num(s.stats.gachaDraws)}回 · 最新48枚</small></div>${recent.length?`<div class="gacha-history">${recent.map(item=>{const o=game.officer(item.officerId,item.rank);return `<button data-action="officer" data-id="${o.id}" data-rank="${item.rank}" class="gacha-history-row"><span class="gacha-history-rank rank-${item.rank}">${item.rank}</span><span><b>${esc(o.name)}</b><small>${esc(o.clan)} · ${shortDate(item.turn)}</small></span><small class="${item.isNew?'new-officer':''}">${item.isNew?(item.isNewOfficer?'新家臣・新絵巻':item.upgraded?'新絵巻・能力上昇':'新たな絵巻'):`同一絵巻 · 勾玉+${item.duplicateRefund}`}</small></button>`;}).join('')}</div>${pageControls('gacha-history-page',gachaHistoryPage,pages)}`:'<div class="panel empty"><p>招集した武将の記録が、ここに残ります。</p><p class="subtitle">まずは1回、あるいは10回。新たな出会いを軍団や城下の力に。</p></div>'}`;}
  function gachaOfficerOddsRows(rank,page){const odds=game.gachaOdds().find(r=>r.rank===rank);if(!odds)return'';const all=game.gachaPool(rank).map(o=>game.officer(o.id,rank)).sort((a,b)=>a.name.localeCompare(b.name,'ja')),list=page===undefined?all:all.slice((page-1)*10,page*10);return list.map(o=>`<tr><th>${esc(o.name)}<small>${esc(o.clan)}</small></th><td class="rank-${rank}">${rank}</td><td>${odds.perOfficerRate.toFixed(4)}%</td></tr>`).join('');}
  function individualOddsPage(){const pages=Math.max(1,Math.ceil(game.gachaPool(gachaOddsRank).length/10));gachaOddsPage=Math.max(1,Math.min(gachaOddsPage,pages));return `<div class="gacha-odds-table-wrap"><table class="gacha-odds-table"><thead><tr><th>武将</th><th>ランク</th><th>提供割合</th></tr></thead><tbody id="gacha-individual-odds">${gachaOfficerOddsRows(gachaOddsRank,gachaOddsPage)}</tbody></table></div>${pageControls('gacha-odds-page',gachaOddsPage,pages)}`;}

  function gachaOddsModal(){const odds=game.gachaOdds();modal('武将招集の提供割合',`${roster.length}名・8ランク · 招集対象 ${num(game.collection().totalVariants)}種 · 1回と10回の各枠は同じ確率です。`,`<div class="notice">先にランクを抽選し、そのランクの対象武将から等確率で1名を選びます。德川家康Uは運営専用のため、通常プレイヤーのUランクは255名です。他のランクは256名です。所持状況・天守レベルは抽選割合に影響しません。確定枠・天井・期間限定武将はありません。</div><div class="gacha-odds-table-wrap"><table class="gacha-odds-table"><thead><tr><th>ランク</th><th>ランク合計</th><th>人数</th><th>武将1名あたり</th></tr></thead><tbody>${odds.map(r=>`<tr><th class="rank-${r.rank}">${r.rank}</th><td>${r.rate}%</td><td>${r.count}名</td><td>${r.perOfficerRate.toFixed(4)}%</td></tr>`).join('')}</tbody></table></div><p class="subtitle">表示は小数第4位まで。厳密な個別割合は「ランク合計 ÷ そのランクの対象人数」です。同じ武将・同じランクの重複だけが勾玉${data.gacha.duplicateRefund}に変換されます。</p><details class="gacha-all-officers"><summary>ランク別・対象武将の個別提供割合</summary><label for="gacha-odds-rank" style="margin-top:17px">確認するランク</label><select id="gacha-odds-rank" class="select">${data.ranks.map(rank=>`<option value="${rank}" ${rank===gachaOddsRank?'selected':''}>${rank}ランク · ${game.gachaPool(rank).length}名</option>`).join('')}</select><div id="gacha-individual-list">${individualOddsPage()}</div></details>`,`<button class="button primary" data-action="close">招集画面へ戻る</button>`,'gacha-odds');}
  function gachaResult(result){modal(result.results.length===10?'十連招集の結果':'武将招集の結果',`新規絵巻 ${result.newCount}枚 · 新たな家臣 ${result.newOfficerCount}名 · 重複変換 勾玉${num(result.refund)}`,`<div class="gacha-result-summary"><span>消費 ${icon('magatama')}${num(result.cost)}</span><span>現在の勾玉 <b data-magatama-balance>${num(state().magatama)}</b></span></div><div class="gacha-result-grid ${result.results.length===1?'single-draw':''}">${result.results.map(item=>`<div class="gacha-draw-result" data-rank="${item.rank}"><div class="gacha-result-label ${item.isNew?'new-officer':''}">${item.isNew?(item.isNewOfficer?'NEW · 新家臣・新絵巻':item.upgraded?'NEW · 上位絵巻':'NEW · 新たな絵巻'):`同一絵巻 · 勾玉+${item.duplicateRefund}`}</div>${officerCard(game.officer(item.officerId,item.rank))}</div>`).join('')}</div><p class="subtitle">絵巻を押すとそのランクの姿・能力・特技を確認できます。上位ランクを獲得すると軍団・奉行の能力が自動で向上します。下位ランクの新規獲得で能力が下がることはありません。</p>`,`<button class="button" data-action="close">招集画面へ</button><button class="button gold" data-view="army">${icon('swords')}軍団を編成</button>`,'gacha-result');playNote(784,.12);}
  function drawDurableOfficers(count){
    if(!canMutate())return{ok:false,message:syncMessage()};
    if(!saveEnabled)return{ok:false,message:'自動保存が停止中です。「保存・設定」で保存状態を確認してから招集してください。'};
    const before=JSON.parse(JSON.stringify(state())),result=game.drawOfficers(count);
    if(!result.ok)return result;
    if(!save()){game.state=before;renderHeader();refreshLiveControls();return{ok:false,retryable:true,message:'保存できなかったため、招集と勾玉の消費を取り消しました。保存状態を確認してから再度お試しください。'};}
    preserveInteraction($('#main'),render);return result;
  }
  function officerModal(id,rank){const o=game.officer(id,rank);if(!o)return;const owned=state().officers.includes(id),variantOwned=game.ownsVariant(id,o.rank),highest=game.highestOwnedRank(id),can=game.canRecruitOfficer(id),ranks=game.ownedRanks(id),recruitRank=game.canOwnOfficerVariant(id,o.baseRank)?o.baseRank:'SSS';modal(o.name,`${o.clan} · ${o.region} · 絵巻 ${ranks.length} / 8種`,`<div class="variant-tabs" role="group" aria-label="絵巻のランクを選ぶ">${data.ranks.map(r=>`<button data-action="officer-rank-detail" data-id="${id}" data-rank="${r}" class="${r===o.rank?'active':''} ${game.ownsVariant(id,r)?'variant-owned':''}" aria-pressed="${r===o.rank}"><b class="rank-${r}">${r}</b><small>${game.ownsVariant(id,r)?'所持':'未所持'}</small></button>`).join('')}</div><div class="officer-detail-top illustrated-officer" data-rank="${o.rank}"><div class="officer-detail-portrait">${portrait(o)}</div><div><span class="eyebrow">${esc(o.rank)} · ${variantOwned?'所持する絵巻':'未所持の絵巻'}</span><h3>${esc(o.name)}</h3><span class="skill-tag" style="border:0;padding:0;margin:0">${icon(skillIcons[o.skill]||'flag')}${esc(skillNames[o.skill]||o.skill)}</span><p class="subtitle">最高所持ランク：${highest||'未登用'}</p></div></div><div class="stats-bars">${[['lead','統率'],['valor','武勇'],['intellect','知略'],['politics','政治']].map(([k,n])=>`<div class="stat-bar"><label>${n}<b>${o[k]}</b></label><div class="progress"><i style="width:${o[k]}%"></i></div></div>`).join('')}</div><p class="subtitle">${o.rank}絵巻の能力：基礎能力に各 +${o.rankBonus}（上限100）。軍団・奉行には所持する最高ランクの能力が自動で反映されます。</p><p>${esc(o.description||`${o.clan}にゆかりのある人物。`)}</p><div class="notice"><strong>${esc(skillNames[o.skill]||o.skill)}</strong><br>${esc(skillDescriptions[o.skill]||'能力と任命先に応じて軍団・施設を支えます。')}<br>軍団内で同じ特技は重複しません。同一人物を別ランクで重複編成することもできません。</div>${!variantOwned?`<p class="subtitle">${game.canOwnOfficerVariant(id,o.rank)?`この${o.rank}絵巻は未所持です。同じ人物の別ランクも新規獲得になります。`:'德川家康のUランクは運営専用の絵巻です。通常プレイヤーはSSS以下を獲得できます。'}</p>`:''}${!owned?`<h3>${recruitRank}絵巻で直接登用</h3><p>直接登用では ${recruitRank} 絵巻を獲得します。天守 Lv.${can.requiredLevel}以上 · 指示1回</p>${costHtml({gold:can.cost})}<p data-recruit-reason="${id}" style="color:var(--gold)">${!can.ok?esc(can.reason):''}</p>`:`<p style="margin-top:16px">${state().army.includes(id)?'出陣軍団に所属しています。':Object.values(state().governors).includes(id)?'施設の奉行を務めています。':'軍団への編成、または奉行への任命ができます。'}</p>`}`,`<button class="button" data-action="close">閉じる</button><button class="button gold" data-action="open-gacha">${icon('magatama')}武将招集</button>${owned?'<button class="button primary" data-view="army">軍団を編成</button>':`<button class="button primary" data-action="recruit-officer" data-id="${id}" ${!can.ok?'disabled':''}>${recruitRank}で登用</button>`}`,'officer',{id,rank:o.rank});}
  function renderArmy(){const s=state(),stats=game.armyStats();return heading('軍団編成','YOUR ARMY · 兵を知り、将を知る','三名の将を選び、次の合戦に備える。')+`<div class="army-layout"><div class="left-column"><div class="army-slots">${[0,1,2].map((slot)=>{const o=game.officer(s.army[slot]);return `<section class="army-slot"><span class="slot-label">${['総大将','副将・一','副将・二'][slot]}</span>${officerCrest(o)}<h3>${o?`<span class="officer-rank-label rank-${o.rank}">${esc(o.rank)}</span> ${esc(o.name)}`:'未任命'}</h3><small>${o?`統率 ${o.lead} · 武勇 ${o.valor}`:'家臣から武将を選択'}</small><br><button class="button small" data-action="pick-army" data-slot="${slot}">${o?'武将を変更':'武将を任命'}</button></section>`;}).join('')}</div><section class="panel"><div class="panel-heading"><h2>兵を集める</h2>${icon('swords')}</div><p class="subtitle">兵数 ${num(s.troops)} / ${num(game.troopCapacity())}人 · 兵舎の増築で上限が増加</p><div class="enlist-form"><label for="recruit-amount" class="subtitle">人数</label><input id="recruit-amount" class="input" type="number" min="100" max="20000" step="100" value="1000" inputmode="numeric"><button class="button primary" data-action="recruit-troops" ${s.command<1||s.gameOver?'disabled':''}>${icon('users')}募兵する</button></div><div id="recruit-cost">${costHtml(game.recruitTroopCost(1000))}</div><p class="subtitle">募兵・訓練はそれぞれ指令1回。指令は1倍速で20秒ごとに1回復します。</p><hr class="divider"><div class="stat-row"><span>士気</span><b>${s.morale} / 100</b></div><div class="progress"><i style="width:${s.morale}%"></i></div>${costHtml(game.trainingCost?game.trainingCost():{gold:180,rice:250})}<button class="button full" data-action="train" ${s.morale>=100||s.command<1||s.gameOver?'disabled':''}>${icon('flag')}軍団を訓練する</button></section><div class="section-heading"><h2>${icon('swords')}合戦の戦法</h2><small>出陣ごとに選択できます</small></div><div class="tactics-grid">${data.tactics.map(t=>`<div class="tactic-card"><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p></div>`).join('')}</div></div><aside><section class="panel"><div class="panel-heading"><h2>軍団の平均能力</h2>${icon('flag')}</div>${[['lead','統率'],['valor','武勇'],['intellect','知略']].map(([k,n])=>`<div class="stat-row"><span>${n}</span><b>${stats[k]}</b></div>`).join('')}<div class="notice">軍団には同じ武将を重複して編成できません。奉行に任命すると軍団から外れます。</div><button class="button primary full" data-view="map" style="margin-top:18px">${icon('map')}天下地図から出陣</button></section><section class="panel"><div class="panel-heading"><h2>補給の見通し</h2>${icon('wheat')}</div><div class="stat-row"><span>月間兵糧生産</span><b>+${num(game.income().grossRice)}</b></div><div class="stat-row"><span>兵・城の維持費</span><b>−${num(game.income().upkeep)}</b></div><div class="stat-row"><span>差引</span><b style="color:${game.income().rice<0?'#d8837a':'var(--green)'}">${game.income().rice>=0?'+':''}${num(game.income().rice)}</b></div><p class="subtitle">兵糧不足は兵の脱走と士気低下につながります。</p></section></aside></div>`;}
  function pickOfficer(mode,target,page=1){choiceMode=mode;choiceTarget=target;const s=state(),list=s.officers.map(id=>game.officer(id)).filter(Boolean).sort((a,b)=>mode==='army'?b.lead-a.lead:b.politics-a.politics),pages=Math.max(1,Math.ceil(list.length/8));choicePage=Math.max(1,Math.min(page,pages));modal(mode==='army'?'出陣する将を選ぶ':'奉行を任命する',mode==='army'?'編成には指示を使いません。':`${game.governorDescription?.(target)||governorHelp[target]||'施設の働きを高めます。'}任命には指示を使いません。`,`<div class="officer-choice-list">${list.slice((choicePage-1)*8,choicePage*8).map(o=>`<button class="officer-choice" data-action="${mode==='army'?'assign-army':'assign-governor'}" data-id="${o.id}" data-target="${target}">${officerCrest(o)}<span class="officer-choice-description"><b><span class="officer-rank-label rank-${o.rank}">${esc(o.rank)}</span> ${esc(o.name)}</b><br><small>統率 ${o.lead} · 武勇 ${o.valor} · 政治 ${o.politics}</small></span><small>${s.army.includes(o.id)?'軍団':Object.values(s.governors).includes(o.id)?'奉行':'待機'}</small></button>`).join('')}</div>${pageControls('choice-page',choicePage,pages)}`,`<button class="button ghost" data-action="${mode==='army'?'remove-army':'remove-governor'}" data-target="${target}">任命を解除</button><button class="button" data-action="close">閉じる</button>`,'officer-select');}
  function renderResearch(){const s=state();return heading('技術研究','RESEARCH · 富国強兵','学問を育て、内政と軍事に新たな力を。')+`<div class="notice">学問所 Lv.${s.buildings.academy} · 研究は同時に1つまで。技術レベルは学問所のレベルが上限となり、最大Lv.5です。</div><div class="research-grid">${data.techs.map(t=>{const lv=s.tech[t.id]||0,job=currentJob('research',t.id),cost=game.researchCost(t.id),max=lv>=t.max,locked=lv>=s.buildings.academy;return `<section class="research-card">${icon(t.icon)}<h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="stat-row"><span>研究レベル</span><b>Lv.${lv} / ${t.max}</b></div><div class="progress"><i style="width:${lv/t.max*100}%"></i></div>${max?'<p class="notice">研究完了</p>':job?`<div class="notice">研究中 · <span data-job-clock="${job.kind}:${job.id}">${esc(jobClockText(job))}</span>${sharedJobAttribution(job)}</div><div class="progress"><i data-job-progress="${job.kind}:${job.id}" style="width:${game.constructionProgress(job)}%"></i></div>`:`${costHtml(cost)}<button class="button ${locked?'':'gold'} full" data-action="research" data-id="${t.id}" ${locked||s.command<1||!hasResources(cost)||s.jobs.some(j=>j.kind==='research')||s.gameOver?'disabled':''}>${locked?'学問所の増築が必要':'研究を始める'}</button>`}</section>`;}).join('')}</div>`;}
  function renderCouncil(){const s=state(),questPages=Math.max(1,Math.ceil(data.quests.length/4)),logPages=Math.max(1,Math.ceil(s.log.length/5));questPage=Math.max(1,Math.min(questPage,questPages));logPage=Math.max(1,Math.min(logPage,logPages));return heading('軍議','COUNCIL · 進むべき道','功績を重ね、天下への歩みを記す。')+`<div class="council-grid"><section><div class="section-heading" style="margin-top:0"><h2>${icon('target')}領主の任務</h2><small>${s.claimedQuests.length} / ${data.quests.length} 達成報酬受取済み</small></div><div class="quest-list">${data.quests.slice((questPage-1)*4,questPage*4).map(q=>{const a=game.questStatus(q.id);return `<section class="quest-row"><div class="quest-emblem">${icon(a.claimed?'check':a.complete?'crown':'flag')}</div><div class="quest-content"><h3>${esc(q.name)}</h3><p>${esc(q.description)} ${a.progress} / ${a.target}</p><div class="progress"><i style="width:${Math.min(100,a.progress/a.target*100)}%"></i></div></div><div class="quest-reward">${Object.keys(q.reward).map(k=>`${k==='magatama'?'勾玉':resNames[k]} +${num(q.reward[k])}`).join('<br>')}</div><button class="button small ${a.complete&&!a.claimed?'gold':''}" data-action="claim-quest" data-id="${q.id}" ${!a.complete||a.claimed?'disabled':''}>${a.claimed?'受取済み':a.complete?'報酬を受け取る':'挑戦中'}</button></section>`;}).join('')}</div>${pageControls('quest-page',questPage,questPages)}</section><section><div class="section-heading"><h2>${icon('scroll')}領国の戦記</h2><button class="text-link" data-action="export-save">この戦記を保存</button></div><section class="panel log-panel">${s.log.slice((logPage-1)*5,logPage*5).map(l=>`<div class="activity-item"><small>${shortDate(l.turn)}</small><p>${esc(logText(l.text))}</p></div>`).join('')}</section>${pageControls('log-page',logPage,logPages)}</section></div>`;}

  function battleModal(id,preserve=false){syncMusic('battle');const c=game.castle(id);if(!c)return;battleTarget=id;if(!preserve){battleTactic='balanced';battleTroops=state().troops;}const p=game.previewBattle(id,battleTactic,battleTroops);modal(`${c.name}への出陣`,`${c.owner} · ${c.province}国`,`<div class="stat-comparison"><div><small>出陣する兵</small><b id="battle-troop-count" class="large-stat">${num(battleTroops)}</b><small>${state().army.map(i=>esc(game.officer(i)?.name)).join('・')||'武将未任命'}</small></div><span class="versus">対</span><div><small>城を守る兵</small><b id="battle-enemy-count" class="large-stat">${num(c.troops)}</b><small id="battle-enemy-wall">城郭 Lv.${c.level} · 城壁 Lv.${c.wall}</small></div></div><div class="form-row"><label for="battle-troops" class="inline-label"><span>出陣兵数</span><span>${num(battleTroops)} / ${num(state().troops)}人</span></label><input id="battle-troops" class="range" type="range" min="${Math.min(300,state().troops)}" max="${state().troops}" step="1" value="${battleTroops}"></div><label for="battle-tactic">戦法を選ぶ</label><select id="battle-tactic" class="select">${data.tactics.map(t=>`<option value="${t.id}" ${battleTactic===t.id?'selected':''}>${esc(t.name)} — ${esc(t.description)}</option>`).join('')}</select><div style="margin:18px 0" id="battle-preview">${battlePreview(p)}</div><div class="notice">出陣は指示1回を使います。合戦では兵を失うことがあります。勝率は戦力差による予測で、勝利の保証ではありません。</div>`,`<button class="button" data-action="close">再考する</button><button id="attack-confirm" class="button primary" data-action="attack" ${!p.ok?'disabled':''}>${icon('swords')}出陣する</button>`,'battle');}
  function battlePreview(p){return `<div class="battle-chance">予想勝率 <b>${p.winChance}%</b></div><div class="stat-row"><span>自軍戦力 / 敵軍戦力</span><b>${num(p.attackPower)} / ${num(p.defensePower)}</b></div><div class="cost"><span>${icon('wheat')}兵糧 ${num(p.foodCost)}</span>${p.scouted?`<span>${icon('eye')}偵察補正 +10%</span>`:''}</div>${!p.ok?`<p style="color:#e7a194;font-size:13px">${esc(p.message)}</p>`:''}`;}
  function updateBattlePreview(){if(!$('#battle-preview'))return;const c=game.castle(battleTarget),s=state(),slider=$('#battle-troops');battleTroops=Math.max(0,Math.min(battleTroops,s.troops));if(slider){slider.min=Math.min(300,s.troops);slider.max=s.troops;if(Number(slider.value)!==battleTroops)slider.value=battleTroops;}const p=game.previewBattle(battleTarget,battleTactic,battleTroops);$('#battle-preview').innerHTML=battlePreview(p);$('#battle-troop-count').textContent=num(battleTroops);$('#attack-confirm').disabled=!p.ok;if(c){$('#battle-enemy-count').textContent=num(c.troops);$('#battle-enemy-wall').textContent=`城郭 Lv.${c.level} · 城壁 Lv.${c.wall}`;const subtitle=$('#modal .modal-header p');if(subtitle)subtitle.textContent=`${c.owner} · ${c.province}国`;}const label=$('label[for="battle-troops"]');if(label)label.innerHTML=`<span>出陣兵数</span><span>${num(battleTroops)} / ${num(s.troops)}人</span>`;}
  function battleResult(b){syncMusic(b.won?'victory':'defeat');modal(b.won?'戦勝の報せ':'撤退の報せ',`${shortDate()} · ${b.castleName}`,`<div class="battle-result ${b.won?'':'lost'}"><div class="eyebrow">${b.won?'VICTORY':'RETREAT'}</div><h2>${b.won?'勝鬨':'退却'}</h2><p class="subtitle">${b.won?`${esc(b.castleName)}があなたの領国に加わりました。`:'兵を立て直し、次の機会をうかがいましょう。'}</p></div><div class="stat-comparison"><div><small>自軍の損失</small><b class="large-stat">${num(b.ourLost)}</b><small>出陣 ${num(b.ourBefore)}人</small></div><span class="versus">/</span><div><small>敵軍の損失</small><b class="large-stat">${num(b.enemyLost)}</b><small>守備 ${num(b.enemyBefore)}人</small></div></div><div class="stat-row"><span>城の守備隊へ配置</span><b>${num(b.garrison||0)} 人</b></div><div class="stat-row"><span>出陣軍から帰還</span><b>${num(Math.max(0,b.ourBefore-b.ourLost-(b.garrison||0)))} 人</b></div><p class="subtitle">帰還兵は待機兵に戻ります。新領地の守備兵は、出陣できる兵数と別に管理します。</p><div class="battle-phases">${(b.phases||[]).map(p=>`<div class="battle-phase"><b>${esc(p.title)}</b><p>${esc(p.text)}</p></div>`).join('')}</div>${b.rewards?.gold||b.rewards?.rice?`<h3>戦利品</h3>${costHtml(b.rewards)}`:''}${b.capturedOfficer?`<div class="notice">${esc(typeof b.capturedOfficer==='string'?(game.officer(b.capturedOfficer)?.name||b.capturedOfficer):b.capturedOfficer.name)}が家臣に加わりました。</div>`:''}`,`<button class="button primary" data-action="close">領国へ戻る</button>`,'result');}
  function settingsModal(){modal('保存・設定','あなたの歩みを、次の一手へ。',`${saveWarning?`<div class="notice">${esc(saveWarning)}</div>`:''}<div class="settings-stack"><button class="button" data-action="open-recovery">${icon('upload')}<span>引き継ぎ・データ復元<small>ドメイン変更・機種変更後に、元の領主と進行へ戻ります。</small></span></button><button class="button" data-action="export-complete-backup">${icon('save')}<span>領主と進行をまとめて書き出す<small>ログイン情報とセーブを一つのバックアップへ。</small></span></button><button class="button" data-action="open-sync">${icon('refresh')}<span>端末同期・運営の引き継ぎ<small>${esc(syncAccess.linked?syncMessage():'同じ領主IDを連携すると、進行を自動で共有します。')}</small></span></button><button class="button" data-action="export-sync-backup">${icon('download')}<span>同期・読込前のセーブを取り出す<small>置き換え前のバックアップをJSONで書き出します。</small></span></button>${game.isAdmin?`<div class="notice admin-fixed-base">${icon('castle')}<strong>運営本拠：江戸城（固定）</strong><br>武将・施設・資源は連携した端末へ引き継ぎます。</div><button class="button gold" data-action="restore-admin-assets">${icon('crown')}<span>德川家康 U を復元<small>運営権限を確認済み。何度押しても重複付与しません。</small></span></button>`:''}<button class="button" data-action="open-gacha">${icon('magatama')}<span>武将招集・勾玉<small>所持 ${num(state().magatama)} · プレイで集める専用通貨。</small></span></button><button class="button" data-action="export-save">${icon('download')}<span>セーブデータを書き出す<small>JSONファイルとして保存。他の端末へ引き継げます。</small></span></button><button class="button" data-action="import-save">${icon('upload')}<span>セーブデータを読み込む<small>確認後に、現在のプレイへ反映します。</small></span></button><button class="button" data-action="install">${icon('plus')}<span>ホーム画面に追加<small>スマホからアプリのように起動。</small></span></button></div><hr class="divider"><div class="settings-row"><label>BGM · 全16曲</label><button class="button small" data-action="sound-settings">${settings.sound?'再生中 · 停止':'停止中 · 再生'}</button></div><p class="notice">BGMを再生すると、対応するスマホ・タブレットではマナーモード中も音が鳴ります。端末のメディア音量を上げ、最初に再生ボタンをタップしてください。</p><button class="button gold full" style="margin-top:14px" data-action="music">${icon('sound')}音楽帳を開く · 16曲から選ぶ</button><div class="settings-row"><label for="volume">音量</label><input id="volume" type="range" min="0" max="100" step="1" value="${settings.volume}" aria-label="BGM音量"></div><div class="settings-row"><label for="tips">城下町のヒント</label><select id="tips" class="select"><option value="on" ${settings.tips?'selected':''}>表示する</option><option value="off" ${settings.tips?'':'selected'}>表示しない</option></select></div><div class="settings-row"><span style="font-size:14px">現在の難易度</span><span style="font-size:13px;color:var(--gold)">${({easy:'初陣',normal:'戦国',hard:'修羅'})[state().difficulty]}</span></div><button class="button danger full" style="margin-top:23px" data-action="new-game">${icon('refresh')}新しい物語を始める</button><div class="notice">未連携ではこのブラウザに自動保存します。領主登録・端末連携後は同じIDの進行を自動同期します。操作できる端末は同時に1台です。通信が切れても世界の時間は進み続け、再接続時に共通時刻へ追いつきます。通信を確認できるまで操作は待機します。領主データとセーブは書き出して保管できます。</div>`,`<button class="button" data-action="help">遊び方</button><button class="button primary" data-action="close">ゲームへ戻る</button>`,'settings');}
  function helpModal(){modal('天下への道しるべ','月を重ね、城を育て、将とともに天下へ。',`<div class="help-steps">${[['城下を育てる','田畑は兵糧、商家は金銭を生みます。施設を選んで増築すると表示された秒数で完成。木材と石材も計画的に確保しましょう。'],['武将を迎える','名鑑から武将を登用するほか、勾玉で武将招集ができます。勾玉は毎月・任務・城の初攻略で集まります。軍団に最大3名を編成。政治の高い家臣は各施設の奉行に任命し、生産・登用・募兵・防衛・研究を支えます。'],['時を味方にする','資源は毎秒、普請と研究は実時間で進みます。1倍速では指令が20秒ごとに1回復し、60秒がゲーム内の1か月です。時間は全プレイヤー共通。1560〜1615年を周回し、画面を閉じていても進みます。再接続時に経過した分を反映します。速度・停止は運営が全員分を管理します。'],['軍備を整える','募兵と訓練で兵数と士気を確保します。兵糧は軍の維持と出陣に必要です。研究で生産量や戦闘力を強化できます。'],['天下を切り拓く','天下地図で自領に隣接する城を選び、出陣兵数と戦法を決定。偵察や6か月の同盟も活用して運営専用の江戸城・スタッフ専用の駿府城を除く城の統一を目指します。自分の役職で領有できる城の数は画面に表示されます。'],['領主と向き合う','共通フィールドには実際のプレイヤーの本拠が表示されます。拠点を選んで襲撃、外交の提案・承諾を行います。外交が成立した6か月間は互いに攻撃できません。運営の江戸城・スタッフの駿府城は固定本拠で、攻撃対象外です。'],['戦記を守る','端末を連携すると進行を自動同期します。連携前の自動保存や、設定からのセーブ書き出しも利用できます。同じ領主IDを連携した端末へ引き継げます。']].map(([t,p])=>`<div class="help-step"><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}</div><div class="notice">天下地図はCPU勢力との戦役です。共通フィールドでは他プレイヤーの拠点を選び、襲撃や合意に基づく外交ができます。年月・接続状況・交流も全員で共有します。実在の人物・城を題材に、年代・能力・外交・合戦をゲーム向けに再構成しています。</div>`,`<button class="button primary" data-action="close">城下町へ</button>`,'help');}
  function aboutModal(){const sourceInfo=window.SENGOKU_ROSTER_META;modal('収録・出典について','戦国大戦 · 群雄集結',`<p>戦国から織豊期を中心に${num(roster.length)}名、${new Set(roster.map(o=>o.clan)).size}勢力の人物を収録しています。史料に残る武将を一人残らず網羅した名簿ではありません。人物の改名は原則として同一人物にまとめています。</p><h3>歴史とゲームの関係</h3><p>本作は256名の人物・128城・64施設が登場する「群雄集結」です。通常城と64施設は最大Lv.32、大都市拠点の江戸・駿府・二条・大坂・名古屋は城郭Lv.64まで育成できます。城の姿は32段階で、Lv.33以降も最終形態を使用します。城郭4,096種・施設2,048種の段階別イラストがあります。武将絵巻と合わせて全8,192種を収録し、16曲のオリジナルBGMを収録しています。異なる年代の人物と城が同時に登場します。能力値・格付け・特技・城の勢力配置・施設効果はすべてゲーム用の創作です。武将1名につき8ランク、計2,048種の創作肖像を閲覧・収集できます。肖像は実際の容姿を示すものではありません。</p><h3>資料</h3><ul class="about-links">${(sourceInfo?.sources||[]).map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)}</a></li>`).join('')}</ul><p class="subtitle"><a href="SOURCES.md" target="_blank" rel="noopener">人物資料</a>・<a href="SOURCES-MAP.md" target="_blank" rel="noopener">地図の出典</a>・<a href="SOURCES-KAMON.md" target="_blank" rel="noopener">家紋の出典</a>を確認できます。</p><hr class="divider"><p class="subtitle">ゲーム内城下町：オリジナル生成イラスト<br>音楽：本作独自の自動演奏<br>著作権：© KASAI SOLUTIONS</p>`,`<button class="button primary" data-action="close">閉じる</button>`,'about');}
  function renderStartSelection(){return `<section class="start-campaign-welcome"><div class="start-campaign-emblem" aria-hidden="true">${icon('castle')}</div><div class="eyebrow">YOUR FIRST CASTLE</div><h1>天下への一歩を、<br>好きな城から。</h1><p>${game.isAdmin?'運営の家は德川家、本拠は江戸城です。難易度を決めて出陣しましょう。':game.isStaff?'スタッフの家は德川家、共同本拠は駿府城です。難易度を決めて、共有の城下町から出陣しましょう。':`大都市拠点を除く全国${data.castles.filter(c=>!c.majorCity).length}城から本拠を一つ選び、あなたの旗を掲げましょう。`}<br>選択を確定するまで、新しい進行は保存されません。</p><div class="start-campaign-actions"><button class="button primary" data-action="new-game">${icon('castle')}${game.isAdmin?'江戸城で開始設定':game.isStaff?'駿府城で開始設定':'はじまりの城を選ぶ'}</button><button class="button" data-action="open-recovery">${icon('upload')}以前の領主・運営を復元</button></div><small>以前の進行がある方は、引き継ぎ・データ復元からお戻りください。</small></section>`;}
  function openStartSelection(){if(startPending&&!$('#modal').open&&!document.querySelector('.social-dialog[open]'))newGameModal();}
  function newGameModal(){newClan=game.isAdmin?data.adminClan.name:game.isStaff?data.staffClan.name:state().clan;newStartCastle=game.isAdmin?'edo':game.isStaff?'sunpu':'';drawNewGame();}
  function startCastlePreview(){const chosen=data.castles.find(c=>c.id===newStartCastle),level=game.isStaff&&chosen?.id==='sunpu'?(game.getStaffBase?.()?.castleLevel||1):1;return chosen?`<div class="start-castle-portrait">${window.SengokuArt?.castle(chosen.id,'start-castle-art',level)||icon('castle')}</div><div><span class="start-castle-location">${esc(chosen.region)} · ${esc(chosen.province)}国</span><h3>${esc(chosen.name)}</h3><p>${esc(newClan)}の本拠として、この一城から開始します。</p><div class="start-castle-facts"><span>城郭 Lv.${level} / ${castleLevelLimit(chosen.id)}</span><span>守備兵 1,200人</span></div>${game.isAdmin?'<strong class="start-castle-admin">運営本拠 · 江戸城固定</strong>':game.isStaff?'<strong class="start-castle-admin">スタッフ共同本拠 · 駿府城固定</strong>':''}</div>`:`<div class="start-castle-empty">${icon('map')}<strong>あなたの本拠を選んでください</strong><span>江戸・駿府・二条・大坂・名古屋の大都市拠点を除く${data.castles.filter(c=>!c.majorCity).length}城から選べます。</span></div>`;}

  function drawNewGame(){
    if(game.isAdmin)newClan=data.adminClan.name;else if(game.isStaff)newClan=data.staffClan.name;else if(!data.clans.some(c=>c.name===newClan))newClan=state().clan;
    const choices=game.isAdmin?[data.adminClan]:game.isStaff?[data.staffClan]:data.clans,difficulty=$('#new-difficulty')?.value||state().difficulty,clan=choices.find(c=>c.name===newClan)||choices[0],available=data.castles.filter(c=>!c.majorCity),regions=[...new Set(available.map(c=>c.region))];
    if(game.isAdmin)newStartCastle='edo';else if(game.isStaff)newStartCastle='sunpu';else if(['edo','sunpu'].includes(newStartCastle))newStartCastle='';
    modal(startPending?'はじまりの城を選ぶ':'新しい物語',game.isAdmin?'運営の出発点は、江戸城に固定されています。':game.isStaff?'スタッフは德川家として、共同本拠の駿府城から出発します。':'家を選び、好きな城を一つ本拠に。',`${startPending?`<div class="start-recovery-row"><span>以前のプレイを続ける方・運営の方はこちら</span><button class="button small" data-action="open-recovery">${icon('upload')}以前の領主・運営を復元</button></div>`:''}<div class="new-campaign-layout"><section class="new-campaign-house"><h3><span>一</span> 仕える家</h3><p class="new-campaign-help">${game.isAdmin?'運営の家は德川家に固定されています。':game.isStaff?'スタッフの家は德川家に固定されています。':'家臣と家の特性を選びます。徳川家も選択できます。'}</p><div class="clan-select-grid">${choices.map(c=>`<button class="clan-choice ${newClan===c.name?'active':''}" data-action="choose-clan" data-id="${c.name}" aria-pressed="${newClan===c.name}">${clanCrest(c.name,38)}<span><b>${esc(c.name)}</b><small>${esc(c.leader)}</small></span></button>`).join('')}</div><div class="start-clan-bonus">${clanCrest(clan.name,25)}<strong>${esc(clan.bonus)}</strong></div><div class="form-row"><label for="new-difficulty">難易度</label><select id="new-difficulty" class="select">${[['easy','初陣 — 初めての領主へ'],['normal','戦国 — ほどよい緊張感'],['hard','修羅 — 手強い群雄との戦い']].map(([v,n])=>`<option value="${v}" ${difficulty===v?'selected':''}>${n}</option>`).join('')}</select></div></section><section class="new-campaign-castle"><h3><span>二</span> はじまりの城</h3>${game.isAdmin?'<p class="new-campaign-help">認証済み運営の本拠は江戸城です。ほかの城は選択できません。</p>':game.isStaff?'<p class="new-campaign-help">スタッフの本拠は保護された駿府城です。全スタッフで城郭・城下町の成長を共有します。</p>':`<label for="new-start-castle" class="new-campaign-help">本拠にする城を一つ選択 · 全${available.length}城</label><select id="new-start-castle" class="select" required aria-describedby="start-castle-rule"><option value="" ${!newStartCastle?'selected':''} disabled>城を選んでください</option>${regions.map(region=>`<optgroup label="${esc(region)}">${available.filter(c=>c.region===region).map(c=>`<option value="${c.id}" ${newStartCastle===c.id?'selected':''}>${esc(c.name)}（${esc(c.province)}国）</option>`).join('')}</optgroup>`).join('')}</select>`}<div id="start-castle-preview" class="start-castle-preview" aria-live="polite">${startCastlePreview()}</div><p id="start-castle-rule" class="new-campaign-help">${game.isAdmin?'德川家康 U の特別イラストを所持して開始します。':game.isStaff?'德川家の駿府城と施設は、共同普請の現在の成長を引き継ぎます。武将・資源・研究は個人ごとに育ちます。':'選んだ1城から出発します。大都市拠点の江戸・駿府・二条（京）・大坂・名古屋は最初に選べません。二条・大坂・名古屋は開始後に攻略できます。江戸城は運営専用、駿府城はスタッフ専用で占領されません。德川家康 U は運営専用です。'}</p></section></div><p class="start-save-notice">${startPending?'「この城から始める」で確定するまで、本拠と進行は保存されません。':'確定すると現在の進行を新しい物語に置き換えます。今のセーブは置き換え前のバックアップにも残します。'}</p><p id="start-campaign-sync" class="start-campaign-sync" role="status"></p>`,`<button class="button" data-action="close">${startPending?'あとで選ぶ':'やめる'}</button>${startPending?'':'<button class="button" data-action="export-save">今のセーブを保存</button>'}<button class="button primary" data-action="start-new">この城から始める</button>`,'new');
  }
  function startNewGame(){
    if(!canStartNew()){toast('端末同期と共通時刻を確認しています。確認が終わってから開始してください。',true);return false;}
    const castleId=game.isAdmin?'edo':game.isStaff?'sunpu':$('#new-start-castle')?.value||newStartCastle;
    if(!data.castles.some(c=>c.id===castleId&&(game.isAdmin||game.isStaff&&c.id==='sunpu'||!c.majorCity))){toast('開始する城を一つ選んでください。',true);$('#new-start-castle')?.focus();return false;}
    let candidate;try{
      candidate=new SengokuEngine({clan:newClan,difficulty:$('#new-difficulty')?.value||state().difficulty,officers:roster,isAdmin:game.isAdmin,isStaff:game.isStaff,staffBase:game.getStaffBase?.(),startCastle:castleId});
      const clock=confirmedWorldClock();if(clock)candidate.applyWorldClock(clock);
      backupCurrentSave('new-game');
      localStorage.setItem(saveKey,candidate.exportSave());
    }catch(error){toast('新しい物語を保存できませんでした。これまでの進行は変更していません。端末の保存領域を確認してください。',true);return false;}
    game=candidate;startPending=false;worldCatchingUp=false;lastRealtime=performance.now();saveCounter=0;newStartCastle=castleId;selectedCastle='';filter.page=1;saveEnabled=true;saveWarning='';currentView='town';
    closeModal();history.replaceState(null,'','#town');render();$('#main').scrollTop=0;$('#main').scrollLeft=0;const indicator=$('#save-indicator');if(indicator)indicator.textContent=syncAccess.linked?'端末に保存 · 同期中':'端末に自動保存済み';window.dispatchEvent(new CustomEvent('sengoku:game-saved'));
    toast(`${newClan}の新たな物語が、${data.castles.find(c=>c.id===castleId).name}から始まりました。`);return true;
  }
  function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
  function exportSave(){if(startPending){toast('本拠を決めて物語を開始すると、セーブを書き出せます。');return;}downloadBlob(new Blob([game.exportSave()],{type:'application/json'}),`sengoku-taisen-save-${date().year}-${date().month}.json`);toast('セーブデータを書き出しました。ダウンロード先を確認してください。');}
  let importedGame=null;
  $('#save-import').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(!requireWritable())return;if(file.size>2*1024*1024){toast('セーブファイルが大きすぎます。2MB以下のJSONを選んでください。',true);return;}try{await window.SengokuWorldClock?.refresh();importedGame=SengokuEngine.fromSave(await file.text(),roster,{isAdmin:game.isAdmin,isStaff:game.isStaff,staffBase:game.getStaffBase?.()});const importAuthority=confirmedWorldClock();if(!importAuthority)throw Error('共通時計を確認してから、もう一度読み込んでください。');if(importedGame.state.worldClock?.id===importAuthority.id&&importedGame.state.worldClock.elapsedMs>importAuthority.elapsedMs)throw Error('現在の共通時計より未来のセーブは読み込めません。');modal('セーブを読み込みますか？','現在のプレイは読み込んだ内容に置き換わります。',`<p>${esc(importedGame.state.clan)} · ${shortDate(importedGame.state.turn)}</p><div class="stat-row"><span>家臣</span><b>${importedGame.state.officers.length}名</b></div><div class="stat-row"><span>領有拠点</span><b>${importedGame.ownedCastles().length}城</b></div>`,`<button class="button" data-action="close">やめる</button><button class="button primary" data-action="confirm-import">読み込む</button>`,'import');}catch(e){importedGame=null;toast('このセーブは読み込めません。形式・バージョン・武将データを確認してください。',true);}});

  let installPrompt=null;
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
