    renderHeader();const status=$('#shared-world-status');if(status){status.textContent=worldCatchingUp?'共通時刻までの進行を反映中':shared.message;status.classList.toggle('running',shared.ready&&shared.clock?.running);}
    const p=$('#month-progress');if(p&&shared.clock)p.style.width=shared.clock.calendar.elapsed/60*100+'%';
    if(document.hidden||!shared.ready||!shared.clock||!canMutate(true)){refreshLiveControls();return;}
    const wasCatchingUp=worldCatchingUp,result=game.applyWorldClock(confirmedWorldClock(),{maxSeconds:7200,deferCycleSettlement:syncAccess.linked});worldCatchingUp=Boolean(result.pending);refreshLiveControls();refreshJobTimers();
    if(!result.ok)return;
